(() => {
  'use strict';

  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const app = $('#app');
  const state = {
    token: '', user: null, cart: null, categories: [], garage: [], builds: [], compare: [],
    paymentConfig: null, notifications: { items: [], unread: 0 }, toastTimer: null, searchTimer: null, searchController: null,
  };

  const money = (cents, currency = 'USD') => new Intl.NumberFormat('en-US', { style: 'currency', currency }).format((Number(cents) || 0) / 100);
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c]));
  const titleCase = value => String(value || '').toLowerCase().replace(/(^|[_\s-])\w/g, s => s.toUpperCase()).replaceAll('_', ' ');
  const fmtDate = v => v ? new Date(v).toLocaleDateString(undefined, { year:'numeric', month:'short', day:'numeric' }) : '—';
  const imageOf = p => p?.images?.[0]?.url || '';
  const sellerName = seller => seller?.sellerProfile?.storeName || ([seller?.firstName, seller?.lastName].filter(Boolean).join(' ') || 'Independent seller');
  const stars = rating => rating ? `${'★'.repeat(Math.round(rating))}${'☆'.repeat(Math.max(0, 5 - Math.round(rating)))}` : 'No reviews yet';
  const vehicleName = g => g ? `${g.year} ${g.vehicleVariant?.model?.make?.name || ''} ${g.vehicleVariant?.model?.name || ''} · ${g.vehicleVariant?.engineCode || ''}`.trim() : '';
  const shippingAddressHtml = address => {
    if (!address || typeof address !== 'object') return '<span class="subtle">Shipping address unavailable</span>';
    const name = [address.firstName, address.lastName].filter(Boolean).join(' ');
    const locality = [address.city, address.state, address.postalCode].filter(Boolean).join(', ');
    const lines = [name, address.line1, address.line2, locality, address.country].filter(Boolean);
    return `<address class="seller-destination">${lines.map(line => `<span>${esc(line)}</span>`).join('')}${address.phone ? `<span>${esc(address.phone)}</span>` : ''}</address>`;
  };
  const cleanRouteToInternal = pathname => {
    const clean = String(pathname || '/').replace(/^\/+|\/+$/g, '');
    if (!clean) return '';
    if (clean === 'vehicles') return 'vehicle-finder';
    if (clean === 'marketplace') return 'shop';
    if (clean === 'build-advisor') return 'advisor';
    if (clean.startsWith('products/')) return `product/${clean.slice(9)}`;
    if (clean.startsWith('orders/')) return `order/${clean.slice(7)}`;
    if (clean.startsWith('sellers/')) return `seller-profile/${clean.slice(8)}`;
    if (clean.startsWith('public-builds/')) return `public-build/${clean.slice(14)}`;
    if (clean.startsWith('builds/')) return `build/${clean.slice(7)}`;
    if (clean === 'marketplace') return 'shop';
    return clean;
  };
  const internalToCleanRoute = raw => {
    const [pathPart = '', queryPart = ''] = String(raw || '').replace(/^#\/?/, '').split('?');
    let path = pathPart.replace(/^\/+|\/+$/g, '');
    if (!path) path = '';
    else if (path === 'vehicle-finder') path = 'vehicles';
    else if (path === 'advisor') path = 'build-advisor';
    else if (path.startsWith('product/')) path = `products/${path.slice(8)}`;
    else if (path.startsWith('order/')) path = `orders/${path.slice(6)}`;
    else if (path.startsWith('seller-profile/')) path = `sellers/${path.slice(15)}`;
    else if (path.startsWith('public-build/')) path = `public-builds/${path.slice(13)}`;
    else if (path.startsWith('build/')) path = `builds/${path.slice(6)}`;
    const qs = new URLSearchParams(queryPart);
    if (path === 'shop' && qs.get('source') === 'MARKETPLACE' && [...qs.keys()].length === 1) return '/marketplace';
    const query = qs.toString();
    return `/${path}${query ? `?${query}` : ''}`;
  };
  const adoptLegacyHash = () => {
    if (!location.hash.startsWith('#/')) return false;
    const target = internalToCleanRoute(location.hash);
    history.replaceState(null, '', target);
    return true;
  };
  const queryFromHash = () => {
    const internal = cleanRouteToInternal(location.pathname);
    const params = new URLSearchParams(location.search);
    if (location.pathname.replace(/\/+$/, '') === '/marketplace') params.set('source', 'MARKETPLACE');
    return { path: internal, params };
  };
  const navigate = target => {
    const clean = String(target).startsWith('#/') ? internalToCleanRoute(target) : String(target || '/');
    history.pushState(null, '', clean);
    route();
  };
  function setPageMeta(title, description, canonicalPath = location.pathname) {
    document.title = title;
    const descriptionMeta = document.querySelector('meta[name="description"]');
    if (descriptionMeta && description) descriptionMeta.content = description;
    let canonical = document.querySelector('link[rel="canonical"]');
    if (!canonical) { canonical = document.createElement('link'); canonical.rel = 'canonical'; document.head.appendChild(canonical); }
    canonical.href = `${location.origin}${canonicalPath}`;
  }
  const requireLogin = (copy = 'Log in to use this feature.') => { if (state.token) return true; openAuth('login'); toast(copy); return false; };

  const THEME_KEY = 'sandman-theme';
  try { const savedTheme = localStorage.getItem(THEME_KEY); document.documentElement.dataset.theme = savedTheme === 'dark' ? 'dark' : 'light'; }
  catch { document.documentElement.dataset.theme = 'light'; }
  function currentTheme() { return document.documentElement.dataset.theme === 'light' ? 'light' : 'dark'; }
  function syncThemeUi() {
    const light = currentTheme() === 'light';
    $$('[data-theme-toggle]').forEach(button => {
      const icon = button.querySelector('.theme-icon');
      const label = button.querySelector('.theme-label');
      if (icon) icon.textContent = light ? '☾' : '☼';
      if (label) label.textContent = light ? 'Dark mode' : 'Light mode';
      button.setAttribute('aria-label', light ? 'Switch to dark mode' : 'Switch to light mode');
      button.title = light ? 'Switch to dark mode' : 'Switch to light mode';
    });
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.content = light ? '#f5f1e8' : '#070707';
  }
  function setTheme(theme, persist = true) {
    const next = theme === 'light' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    if (persist) { try { localStorage.setItem(THEME_KEY, next); } catch {} }
    syncThemeUi();
  }
  function toggleTheme() { setTheme(currentTheme() === 'light' ? 'dark' : 'light'); }

  function openActionModal(html) {
    const modal = $('#actionModal');
    $('#actionModalContent').innerHTML = html;
    modal.classList.add('open');
    modal.setAttribute('aria-hidden','false');
    openBackdrop();
    setTimeout(() => modal.querySelector('input,select,textarea,button')?.focus(), 40);
  }
  function closeActionModal() {
    const modal = $('#actionModal');
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden','true');
    closeBackdropIfUnused();
  }
  const reviewVehicleLabel = vehicle => vehicle ? `${vehicle.yearStart}${vehicle.yearEnd !== vehicle.yearStart ? `–${vehicle.yearEnd}` : ''} ${vehicle.model.make.name} ${vehicle.model.name} · ${vehicle.engineCode}` : '';
  const reputationLabel = badge => ({ VERIFIED:'✓ Verified seller', TOP_SELLER:'★ Top seller', EXPERIENCED_SELLER:'50+ sales' }[badge] || titleCase(badge));

  async function openReviewComposer({ productId, orderItemId, sellerId, productName }) {
    openActionModal(`<span class="eyebrow">VERIFIED PURCHASE REVIEW</span><h2 id="actionModalTitle">Review ${esc(productName)}.</h2><p>Add a rating, useful fitment notes and optional photos of the part installed.</p><form id="reviewComposer" class="market-form"><div class="modal-form-grid"><label>Rating<select name="rating" required>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label><label>Title<input name="title" maxlength="120" placeholder="Great fit on my build"></label><label class="full">Review<textarea name="body" rows="5" maxlength="3000" placeholder="What vehicle did you install it on? How was fitment and quality?"></textarea></label><label class="full upload-drop">Add photos<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><span class="upload-drop-icon">＋</span><strong>Choose up to 5 photos</strong><small>JPG, PNG or WebP</small></label><div class="full review-upload-grid" id="reviewUploadPreview"></div>${sellerId?'<label class="check-line full"><input name="rateSeller" type="checkbox"> Also rate this marketplace seller</label><label id="sellerRatingField" hidden>Seller rating<select name="sellerRating">'+[5,4,3,2,1].map(n=>`<option value="${n}">${n} / 5</option>`).join('')+'</select></label>':''}</div><button class="primary-btn wide" type="submit">Publish verified review</button></form>`);
    const form=$('#reviewComposer'), input=form.elements.photos, preview=$('#reviewUploadPreview');
    input.onchange=()=>{const files=[...input.files].slice(0,5);preview.innerHTML=files.map(file=>`<span>${esc(file.name)}</span>`).join('');};
    form.elements.rateSeller?.addEventListener('change',e=>$('#sellerRatingField').hidden=!e.target.checked);
    form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Uploading…';try{const data=new FormData(form);const files=[...input.files].slice(0,5);const uploaded=files.length?await uploadProductImages(files,'reviews'):[];await api(`/reviews/products/${productId}`,{method:'POST',body:JSON.stringify({orderItemId,rating:Number(data.get('rating')),title:data.get('title')||undefined,body:data.get('body')||undefined,mediaUrls:uploaded.map(item=>item.url)})});if(sellerId&&data.get('rateSeller'))await api(`/reviews/sellers/${sellerId}`,{method:'POST',body:JSON.stringify({orderItemId,rating:Number(data.get('sellerRating')||5)})});toast('Review published');closeActionModal();route();}catch(error){toast(error.message,'error');button.disabled=false;button.textContent='Publish verified review';}};
  }

  async function refreshSession() {
    try {
      const res = await fetch('/api/auth/refresh', { method:'POST', credentials:'same-origin' });
      if (!res.ok) return false;
      const data = await res.json(); setToken(data.token, data.user); return true;
    } catch { return false; }
  }

  async function api(path, options = {}, retry = true) {
    const headers = { ...(options.headers || {}) };
    if (!(options.body instanceof FormData) && options.body !== undefined) headers['Content-Type'] = 'application/json';
    if (state.token) headers.Authorization = `Bearer ${state.token}`;
    const res = await fetch(`/api${path}`, { ...options, headers, credentials:'same-origin' });
    const text = await res.text(); let data = null;
    if (text) { try { data = JSON.parse(text); } catch { data = text; } }
    if (res.status === 401 && retry && !path.startsWith('/auth/login') && !path.startsWith('/auth/register') && !path.startsWith('/auth/refresh')) {
      if (await refreshSession()) return api(path, options, false);
    }
    if (!res.ok) {
      const message = data?.error?.message || data?.error || data?.message || `Request failed (${res.status})`;
      const err = new Error(message); err.status = res.status; throw err;
    }
    return data;
  }

  async function uploadProductImages(files, purpose = 'marketplace') {
    const chosen = [...(files || [])];
    if (!chosen.length) return [];
    if (chosen.length > 8) throw new Error('You can upload up to 8 images at a time.');
    const output = [];
    for (const file of chosen) {
      if (!['image/jpeg','image/png','image/webp'].includes(file.type)) throw new Error(`${file.name} must be JPG, PNG or WebP.`);
      if (file.size > 10 * 1024 * 1024) throw new Error(`${file.name} is larger than 10 MB.`);
      const signature = await api('/uploads/signature', { method:'POST', body:JSON.stringify({ purpose }) });
      const body = new FormData();
      body.append('file', file);
      body.append('api_key', signature.apiKey);
      body.append('timestamp', String(signature.timestamp));
      body.append('folder', signature.folder);
      body.append('public_id', signature.publicId);
      body.append('signature', signature.signature);
      const response = await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(signature.cloudName)}/image/upload`, { method:'POST', body });
      const data = await response.json().catch(() => null);
      if (!response.ok || !data?.secure_url) throw new Error(data?.error?.message || `Could not upload ${file.name}.`);
      output.push({ url:data.secure_url, alt:file.name.replace(/\.[^.]+$/, '').slice(0, 240), position:output.length });
    }
    return output;
  }

  function renderImageManager(root, images, options = {}) {
    const list = root.querySelector('[data-image-list]');
    if (!list) return;
    list.innerHTML = images.length ? images.map((image, index) => `<figure class="upload-thumb" data-image-index="${index}"><img src="${esc(image.url)}" alt="${esc(image.alt || `Product image ${index + 1}`)}"><button type="button" data-remove-image="${index}" aria-label="Remove image">×</button>${index === 0 ? '<figcaption>Cover</figcaption>' : ''}</figure>`).join('') : '<div class="upload-empty">No images yet. Add clear photos from several angles.</div>';
    $$('[data-remove-image]', list).forEach(button => button.onclick = () => {
      images.splice(Number(button.dataset.removeImage), 1);
      images.forEach((image, index) => image.position = index);
      renderImageManager(root, images, options);
    });
  }

  function toast(message, type = '') {
    const el = $('#toast'); clearTimeout(state.toastTimer); el.textContent = message; el.className = `toast show ${type}`;
    state.toastTimer = setTimeout(() => { el.className = 'toast'; }, 3300);
  }
  function setToken(token, user) { state.token = token || ''; state.user = user || null; updateAccountUi(); }
  function updateAccountUi() {
    $('#accountButton').textContent = state.user?.firstName || 'Account';
    const dot = $('#notificationDot'); if (dot) dot.hidden = !(state.notifications.unread > 0);
  }
  async function hydrateUser() {
    if (!state.token) await refreshSession();
    if (!state.token) return;
    try {
      state.user = await api('/auth/me');
      const [garage, cart, notices] = await Promise.all([api('/garage').catch(() => []), api('/cart').catch(() => null), api('/experience/notifications').catch(() => ({ items:[], unread:0 }))]);
      state.garage = garage; state.cart = cart; state.notifications = notices; updateCartCount(); updateAccountUi();
    } catch { setToken('', null); state.garage=[]; state.cart=null; }
  }
  async function loadCategories() { state.categories = await api('/products/categories').catch(() => []); }
  async function loadGarage() { state.garage = state.token ? await api('/garage').catch(() => []) : []; return state.garage; }
  async function loadBuilds() { state.builds = state.token ? await api('/builds').catch(() => []) : []; return state.builds; }
  async function loadNotifications() { state.notifications = state.token ? await api('/experience/notifications').catch(() => ({items:[],unread:0})) : {items:[],unread:0}; updateAccountUi(); return state.notifications; }

  function openBackdrop() { $('#backdrop').classList.add('open'); }
  function closeBackdropIfUnused() { if (!$('#cartDrawer').classList.contains('open') && !$('#authModal').classList.contains('open') && !$('#actionModal').classList.contains('open')) $('#backdrop').classList.remove('open'); }
  function openAuth(tab = 'login') { closeCart(); $('#authModal').classList.add('open'); $('#authModal').setAttribute('aria-hidden','false'); openBackdrop(); switchAuthTab(tab); setTimeout(() => $(`#${tab}Form input`)?.focus(), 120); }
  function closeAuth() { $('#authModal').classList.remove('open'); $('#authModal').setAttribute('aria-hidden','true'); closeBackdropIfUnused(); }
  function switchAuthTab(tab) { $$('.auth-tabs button').forEach(b => b.classList.toggle('active', b.dataset.authTab === tab)); $('#loginForm').classList.toggle('hidden', tab !== 'login'); $('#registerForm').classList.toggle('hidden', tab !== 'register'); }
  function closeMobileMenu(){ $('#mobileMenu').classList.remove('open'); $('#mobileMenu').setAttribute('aria-hidden','true'); document.body.classList.remove('mobile-menu-open'); }
  function closeSearch(){ const panel=$('#searchPanel'); panel?.classList.remove('open'); panel?.setAttribute('aria-hidden','true'); state.searchController?.abort(); }

  async function loadCart(render = true) {
    if (!state.token) { state.cart=null; updateCartCount(); if (render) renderCart(); return; }
    state.cart = await api('/cart').catch(() => null); updateCartCount(); if (render) renderCart();
  }
  function updateCartCount() { $('#cartCount').textContent = state.cart?.items?.reduce((n,i)=>n+i.quantity,0) || 0; }
  async function openCart() { if (!requireLogin('Log in to view your bag.')) return; await loadCart(true); $('#cartDrawer').classList.add('open'); $('#cartDrawer').setAttribute('aria-hidden','false'); openBackdrop(); }
  function closeCart() { $('#cartDrawer').classList.remove('open'); $('#cartDrawer').setAttribute('aria-hidden','true'); closeBackdropIfUnused(); }
  function renderCart() {
    const wrap=$('#cartItems'), foot=$('#cartFooter');
    if (!state.cart?.items?.length) { wrap.innerHTML='<div class="cart-empty"><div><span class="eyebrow">EMPTY BAG</span><p>Find the part your build is waiting for.</p><a class="secondary-btn" href="#/shop" data-close-cart>Shop parts</a></div></div>'; foot.innerHTML=''; $('[data-close-cart]',wrap)?.addEventListener('click',closeCart); return; }
    wrap.innerHTML=state.cart.items.map(item=>{ const p=item.product,img=imageOf(p),price=item.effectiveUnitPriceCents ?? p.priceCents; return `<article class="cart-item" data-cart-id="${esc(item.id)}">${img?`<img src="${esc(img)}" alt="${esc(p.name)}">`:'<div class="skeleton"></div>'}<div><h4>${esc(p.name)}</h4><small>${item.offer?`Accepted offer · ${money(price)}`:`${p.sourceType==='MARKETPLACE'?'Seller listing':'Supplier stock'} · ${money(price)}`}</small><div class="mini-qty"><button data-qty="-1">−</button><span>${item.quantity}</span><button data-qty="1">+</button></div></div><button class="cart-remove" data-remove>Remove</button></article>`; }).join('');
    foot.innerHTML=`<div class="cart-total"><span>Subtotal</span><span>${money(state.cart.subtotalCents)}</span></div><p class="cart-note">Shipping, tax and eligible discounts are calculated at checkout.</p><button class="primary-btn wide" id="checkoutButton">Checkout</button>`;
    $$('.cart-item',wrap).forEach(row=>{ const id=row.dataset.cartId; row.querySelectorAll('[data-qty]').forEach(btn=>btn.addEventListener('click',async()=>{ const current=state.cart.items.find(i=>i.id===id); try{ await api(`/cart/items/${id}`,{method:'PATCH',body:JSON.stringify({quantity:Math.max(1,current.quantity+Number(btn.dataset.qty))})}); await loadCart(true);}catch(e){toast(e.message,'error');} })); row.querySelector('[data-remove]').addEventListener('click',async()=>{ try{await api(`/cart/items/${id}`,{method:'DELETE'});await loadCart(true);}catch(e){toast(e.message,'error');} }); });
    $('#checkoutButton').onclick=()=>{closeCart();location.hash='#/checkout';};
  }
  async function addToCart(productId, quantity=1, vehicleVariantId, offerId) {
    if (!requireLogin('Log in to add parts to your bag.')) return;
    try { await api('/cart/items',{method:'POST',body:JSON.stringify({productId,quantity,vehicleVariantId:vehicleVariantId||undefined,offerId:offerId||undefined})}); await loadCart(false); toast('Added to bag'); openCart(); } catch(e){toast(e.message,'error');}
  }

  function fitBadge(status) {
    if (status==='VERIFIED_FIT') return '<span class="fit-chip fits">✓ Verified fit</span>';
    if (status==='CATALOG_FIT' || status==='FITS') return '<span class="fit-chip catalog-fit">✓ Catalogue fit</span>';
    if (status==='UNIVERSAL') return '<span class="fit-chip fits">✓ Universal</span>';
    if (status==='DOES_NOT_FIT') return '<span class="fit-chip nofit">× Does not fit</span>';
    return '<span class="fit-chip unknown">? Fitment unconfirmed</span>';
  }
  function productCard(p, fitmentStatus) {
    const img=imageOf(p), source=p.sourceType==='MARKETPLACE'?'Marketplace':'Supplier Stock';
    return `<article class="product-card-wrap"><a class="product-card" href="#/product/${encodeURIComponent(p.slug)}"><div class="product-media ${img?'':'empty-media'}">${img?`<img src="${esc(img)}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="640" height="640">`:'<div class="part-glyph">◉</div>'}<div class="product-badges"><span class="badge ${p.sourceType==='MARKETPLACE'?'market':''}">${source}</span>${p.inStock===false?'<span class="badge danger">Sold out</span>':''}</div></div><div class="product-info"><div class="product-meta"><span>${esc(p.brand||'SANDMAN')}</span><span>${esc(p.category?.name||'')}</span></div><h3>${esc(p.name)}</h3>${fitmentStatus?fitBadge(fitmentStatus):''}<div class="rating-line"><span>${esc(stars(p.rating))}</span><small>${p.reviewCount?`${p.reviewCount} review${p.reviewCount===1?'':'s'}`:''}</small></div><div class="price-row"><span class="price">${money(p.priceCents,p.currency||'USD')}</span>${p.compareAtCents?`<span class="compare">${money(p.compareAtCents,p.currency||'USD')}</span>`:''}</div><div class="seller-line">${p.sourceType==='MARKETPLACE'?`Sold by ${esc(sellerName(p.seller))}`:'Fulfilled by connected supplier'}</div></div></a><button class="compare-float" data-compare-id="${esc(p.id)}" data-compare-name="${esc(p.name)}" title="Compare">＋ Compare</button></article>`;
  }
  const cardSkeletons=n=>`<div class="product-grid">${Array.from({length:n},()=>'<div class="product-card"><div class="product-media skeleton"></div><div class="product-info"><div class="skeleton mini"></div><div class="skeleton line"></div><div class="skeleton mini"></div></div></div>').join('')}</div>`;
  function emptyProducts(message){return `<div class="empty-state"><h3>Nothing here yet.</h3><p>${esc(message)}</p></div>`;}
  function bindCompareButtons(root=document){ $$('[data-compare-id]',root).forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const id=btn.dataset.compareId;if(!state.compare.includes(id))state.compare.push(id);state.compare=state.compare.slice(-4);toast(`${btn.dataset.compareName} added to compare`);if(state.compare.length>=2)btn.textContent='✓ Compare ready';})); }

  async function renderHome() {
    app.innerHTML=`<section class="hero"><div class="hero-content"><div class="hero-logo-wrap"><img class="hero-logo" src="/assets/sandman-logo.webp" alt="SANDMAN" width="640" height="640" decoding="async" fetchpriority="high"></div><div class="hero-copy"><span class="kicker">AUTOMOTIVE PARTS PLATFORM / V2.4.1</span><h1 class="display">Find the part.<br><em>Build the car.</em></h1><p>Choose your exact car, verify fitment, compare supplier stock, plan a build and check out from one automotive platform. Search by engine code, chassis, OEM number, SKU or part name.</p><div class="hero-actions"><a class="primary-btn" href="#/vehicle-finder">Find parts for your car</a><a class="secondary-btn" href="#/advisor">Build advisor</a><a class="ghost-btn" href="#/shop">Shop all</a></div></div></div><div class="hero-scroll">Explore the market</div><div class="hero-index"><span>My Garage</span><span>Verified reviews</span><span>Buyer protection</span></div></section>
    <section class="market-search-band"><div class="market-search"><h3>What are you building?</h3><form id="homeSearch"><input name="q" placeholder="B58 turbo, M340i intercooler, OEM number..." autocomplete="off"><button>↗</button></form><span class="market-stat">Search the whole market.</span></div></section>
    <section id="garageHomeSection" class="section compact-section"></section>
    <section class="section"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">TRENDING / SANDMAN</span><h2>What builders are looking at.</h2></div><a class="text-link" href="#/shop?sort=popular">Shop popular</a></div><div id="trendingProducts">${cardSkeletons(8)}</div></div></section>
    <section class="section"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">BROWSE / CATEGORIES</span><h2>Start with the part.</h2></div><p>Search first. Fitment when you need it.</p></div><div class="category-grid" id="homeCategories"></div></div></section>
    <section class="source-split"><a class="source-panel" href="#/shop?source=DROPSHIP"><span class="source-giant">01</span><div class="source-copy"><span class="eyebrow">CONNECTED SUPPLIERS</span><h3>Supplier stock.</h3><p>Live-linked parts, stock and automated fulfillment foundations.</p><span class="secondary-btn">Shop supplier stock</span></div></a><a class="source-panel marketplace" href="#/shop?source=MARKETPLACE"><span class="source-giant">02</span><div class="source-copy"><span class="eyebrow">INDEPENDENT MARKET</span><h3>Rare, used, rebuilt.</h3><p>Buy from independent sellers with offers, messages, seller ratings and buyer protection.</p><span class="secondary-btn">Browse marketplace</span></div></a></section>
    <section class="section"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">MARKETPLACE / LATEST</span><h2>From other garages.</h2></div><a class="text-link" href="#/shop?source=MARKETPLACE">View marketplace</a></div><div id="marketProducts">${cardSkeletons(4)}</div></div></section>`;
    $('#homeSearch').onsubmit=e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('q')?.toString().trim();location.hash=`#/shop${q?`?q=${encodeURIComponent(q)}`:''}`;};
    $('#homeCategories').innerHTML=state.categories.slice(0,8).map((c,i)=>`<a class="category-card" href="#/shop?category=${encodeURIComponent(c.slug)}"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${esc(c.name)}</h3><div class="cat-foot"><span>${c._count?.products||0} listings</span><span>↗</span></div></a>`).join('');
    try {
      const home=await api('/experience/home');
      $('#trendingProducts').innerHTML=home.trending?.length?`<div class="product-grid">${home.trending.map(productCard).join('')}</div>`:emptyProducts('No trending products yet.');
      $('#marketProducts').innerHTML=home.marketplace?.length?`<div class="product-grid">${home.marketplace.slice(0,4).map(productCard).join('')}</div>`:emptyProducts('Seller listings will appear here.');
      const sec=$('#garageHomeSection');
      if(home.primaryGarageVehicle){ const g=home.primaryGarageVehicle; sec.innerHTML=`<div class="section-inner"><div class="garage-banner"><div><span class="eyebrow">YOUR GARAGE / PRIMARY</span><h2>${esc(vehicleName(g))}</h2><p>Showing parts that fit this vehicle or are universal.</p></div><div><a class="secondary-btn" href="#/garage">Manage garage</a><a class="primary-btn" href="#/shop?vehicleVariantId=${encodeURIComponent(g.vehicleVariantId)}">Shop parts that fit</a></div></div>${home.forGarage?.length?`<div class="product-grid">${home.forGarage.slice(0,4).map(p=>productCard(p,'FITS')).join('')}</div>`:''}</div>`; }
      else sec.innerHTML='<div class="section-inner"><div class="garage-banner"><div><span class="eyebrow">MY GARAGE</span><h2>Tell SANDMAN what you drive.</h2><p>Save a car to get fitment badges and vehicle-specific shopping.</p></div><a class="primary-btn" href="#/garage">Add your car</a></div></div>';
      bindCompareButtons(app);
    } catch(e){$('#trendingProducts').innerHTML=emptyProducts(e.message);}
  }

  async function renderShop(params) {
    const keys=['source','q','category','condition','sort','page','minPrice','maxPrice','vehicleVariantId','inStock'];
    const filter={};
    keys.forEach(k=>{ if(params.get(k)) filter[k]=params.get(k); });
    const selectedGarage=state.garage.find(g=>g.vehicleVariantId===filter.vehicleVariantId);
    const primaryGarage=state.garage.find(g=>g.isPrimary) || state.garage[0];
    setPageMeta(filter.q?`${filter.q} parts — SANDMAN`:filter.source==='MARKETPLACE'?'Automotive Marketplace — SANDMAN':'Automotive Parts — SANDMAN', selectedGarage?`Shop parts filtered for ${vehicleName(selectedGarage)}.`:'Search automotive parts by vehicle, engine code, brand, SKU or OEM number.', location.pathname);
    const activeFilterCount=['source','category','condition','vehicleVariantId','inStock','minPrice','maxPrice'].filter(k=>filter[k]).length;
    const qs=new URLSearchParams(filter); qs.set('limit','24');
    app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">SANDMAN / MARKET</span><h1>${filter.q?`Search: ${esc(filter.q)}`:filter.source==='MARKETPLACE'?'Marketplace.':filter.source==='DROPSHIP'?'Supplier stock.':'The market.'}</h1><p>${selectedGarage?`Filtered for ${esc(vehicleName(selectedGarage))}.`:'Search by part, engine code, car, brand, SKU or OEM number.'}</p></div></section><div class="shop-layout"><aside class="filters" id="shopFilters" aria-label="Product filters"><div class="mobile-filter-head"><div><span class="eyebrow">FILTER MARKET</span><strong>Refine parts</strong></div><button class="close-x" id="filterClose" type="button" aria-label="Close filters">×</button></div><div class="filter-block"><div class="filter-title">Vehicle</div>${state.garage.length?`<select id="garageFilter"><option value="">All vehicles</option>${state.garage.map(g=>`<option value="${esc(g.vehicleVariantId)}" ${g.vehicleVariantId===filter.vehicleVariantId?'selected':''}>${esc(vehicleName(g))}</option>`).join('')}</select>`:`<a class="text-link" href="#/garage">+ Add car</a>`}</div><div class="filter-block"><div class="filter-title">Source</div><div class="filter-list"><button data-filter="source" data-value="" class="${!filter.source?'active':''}">All</button><button data-filter="source" data-value="DROPSHIP" class="${filter.source==='DROPSHIP'?'active':''}">Supplier stock</button><button data-filter="source" data-value="MARKETPLACE" class="${filter.source==='MARKETPLACE'?'active':''}">Marketplace</button></div></div><div class="filter-block"><div class="filter-title">Condition</div><select id="conditionFilter"><option value="">Any condition</option>${['NEW','USED','REMANUFACTURED','OPEN_BOX'].map(v=>`<option value="${v}" ${filter.condition===v?'selected':''}>${titleCase(v)}</option>`).join('')}</select></div><div class="filter-block"><div class="filter-title">Category</div><select id="categoryFilter"><option value="">All categories</option>${state.categories.map(c=>`<option value="${esc(c.slug)}" ${filter.category===c.slug?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="filter-block"><label class="check-line"><input id="stockFilter" type="checkbox" ${filter.inStock==='true'?'checked':''}> In stock only</label></div><button class="mobile-filter-apply primary-btn" type="button" id="filterDone">Show results</button></aside><button class="filter-backdrop" id="filterBackdrop" type="button" aria-label="Close filters"></button><section class="shop-main">${primaryGarage&&!selectedGarage?`<div class="personal-shop-banner"><div><strong>Shopping for ${esc(vehicleName(primaryGarage))}?</strong><small>Use your primary Garage vehicle to show only universal or catalogue-linked parts.</small></div><button class="secondary-btn" id="shopMyVehicle" type="button">Show parts for my car</button></div>`:''}<div class="shop-toolbar"><div class="shop-toolbar-left"><span id="resultCount">Loading…</span>${selectedGarage?`<span class="vehicle-context">${esc(vehicleName(selectedGarage))}</span>`:''}</div><div class="shop-toolbar-actions"><button class="mobile-filter-trigger" id="mobileFilterButton" type="button">Filters${activeFilterCount?` <span>${activeFilterCount}</span>`:''}</button><label class="sort-control"><span>Sort</span><select id="sortFilter"><option value="newest">Newest</option><option value="popular">Popular</option><option value="price_asc">Price low-high</option><option value="price_desc">Price high-low</option><option value="name">Name</option></select></label></div></div><div id="shopProducts">${cardSkeletons(12)}</div><div id="pagination" class="pagination"></div></section></div></div>`;
    $('#sortFilter').value=filter.sort||'newest';
    $('#shopMyVehicle')?.addEventListener('click',()=>{const next=new URLSearchParams(params);next.set('vehicleVariantId',primaryGarage.vehicleVariantId);next.delete('page');navigate(`/shop?${next.toString()}`);});
    const navWith=(key,value)=>{const next=new URLSearchParams(params);if(value)next.set(key,value);else next.delete(key);next.delete('page');const query=next.toString();location.hash=`#/shop${query?`?${query}`:''}`;};
    const isMobileFilters=()=>window.matchMedia('(max-width:760px)').matches;
    const draftFilters=new URLSearchParams(params);
    const updateDraft=(key,value)=>{if(value)draftFilters.set(key,value);else draftFilters.delete(key);draftFilters.delete('page');};
    const closeFilters=()=>{$('#shopFilters')?.classList.remove('open');$('#filterBackdrop')?.classList.remove('open');document.body.classList.remove('filters-open');};
    const openFilters=()=>{$('#shopFilters')?.classList.add('open');$('#filterBackdrop')?.classList.add('open');document.body.classList.add('filters-open');};
    $('#mobileFilterButton')?.addEventListener('click',openFilters);
    $('#filterClose')?.addEventListener('click',closeFilters);
    $('#filterBackdrop')?.addEventListener('click',closeFilters);
    $('#filterDone')?.addEventListener('click',()=>{const query=draftFilters.toString();const next=`#/shop${query?`?${query}`:''}`;if(location.hash===next)closeFilters();else location.hash=next;});
    $$('[data-filter]').forEach(b=>b.onclick=()=>{if(!isMobileFilters())return navWith(b.dataset.filter,b.dataset.value);updateDraft(b.dataset.filter,b.dataset.value);$$(`[data-filter="${b.dataset.filter}"]`).forEach(x=>x.classList.toggle('active',x===b));});
    $('#garageFilter')?.addEventListener('change',e=>isMobileFilters()?updateDraft('vehicleVariantId',e.target.value):navWith('vehicleVariantId',e.target.value));
    $('#conditionFilter').onchange=e=>isMobileFilters()?updateDraft('condition',e.target.value):navWith('condition',e.target.value);
    $('#categoryFilter').onchange=e=>isMobileFilters()?updateDraft('category',e.target.value):navWith('category',e.target.value);
    $('#stockFilter').onchange=e=>isMobileFilters()?updateDraft('inStock',e.target.checked?'true':''):navWith('inStock',e.target.checked?'true':'');
    $('#sortFilter').onchange=e=>navWith('sort',e.target.value);
    try {
      const data=await api(`/products?${qs}`);
      $('#resultCount').textContent=`${data.total} part${data.total===1?'':'s'}`;
      $('#shopProducts').innerHTML=data.items.length?`<div class="product-grid">${data.items.map(p=>productCard(p, selectedGarage?(p.fitmentStatus||'CATALOG_FIT'):null)).join('')}</div>`:emptyProducts('Try changing your filters.');
      bindCompareButtons($('#shopProducts'));
      const current=Number(data.page);
      $('#pagination').innerHTML=Array.from({length:data.pages},(_,i)=>i+1).slice(Math.max(0,current-3),Math.min(data.pages,current+2)).map(n=>`<button data-page="${n}" class="${n===current?'active':''}">${n}</button>`).join('');
      $$('[data-page]').forEach(b=>b.onclick=()=>navWith('page',b.dataset.page));
    } catch(e){ $('#shopProducts').innerHTML=emptyProducts(e.message); }
  }

  async function renderProduct(slug) {
    const primary=state.garage.find(g=>g.isPrimary) || state.garage[0];
    app.innerHTML='<div class="product-detail"><div class="product-gallery skeleton"></div><div class="product-panel"><p>Loading part…</p></div></div>';
    try {
      const p=await api(`/products/${encodeURIComponent(slug)}${primary?`?vehicleVariantId=${encodeURIComponent(primary.vehicleVariantId)}`:''}`);
      setPageMeta(p.seoTitle || `${p.name} — SANDMAN`, p.seoDescription || p.shortDesc || p.description.slice(0,155), `/products/${encodeURIComponent(p.slug)}`);
      api(`/experience/products/${p.id}/view`,{method:'POST'}).catch(()=>{});
      const images=p.images?.length?p.images:[]; const gallery=images.length?`<div class="gallery-main"><img id="mainProductImage" src="${esc(images[0].url)}" alt="${esc(p.name)}" decoding="async"></div>${images.length>1?`<div class="gallery-thumbs">${images.map((im,i)=>`<button data-image="${esc(im.url)}" class="${i===0?'active':''}"><img src="${esc(im.url)}" alt="" loading="lazy" decoding="async"></button>`).join('')}</div>`:''}${p.videoUrl?`<a class="video-link" href="${esc(p.videoUrl)}" target="_blank" rel="noreferrer">Watch product video ↗</a>`:''}`:'<div class="empty-media detail-empty">◉</div>';
      const garageOptions=state.garage.map(g=>`<option value="${esc(g.vehicleVariantId)}" ${primary?.vehicleVariantId===g.vehicleVariantId?'selected':''}>${esc(vehicleName(g))}</option>`).join('');
      const seller=p.seller; const profile=seller?.sellerProfile;
      app.innerHTML=`<div class="product-detail"><div class="product-gallery">${gallery}</div><div class="product-panel"><div class="product-badges"><span class="badge ${p.sourceType==='MARKETPLACE'?'market':''}">${p.sourceType==='MARKETPLACE'?'Marketplace':'Supplier Stock'}</span><span class="badge">${titleCase(p.condition)}</span>${p.inStock?'':'<span class="badge danger">Sold out</span>'}</div><div class="product-meta"><span>${esc(p.brand||'SANDMAN')}</span><span>${esc(p.manufacturerPn||p.sku)}</span></div><h1>${esc(p.name)}</h1><div class="rating-line large"><span>${esc(stars(p.rating))}</span><small>${p.reviewCount} verified review${p.reviewCount===1?'':'s'}</small></div><div class="product-price">${money(p.priceCents,p.currency)}</div><p class="product-description">${esc(p.shortDesc||p.description)}</p>
      ${p.requiresFitment&&!p.isUniversal?`<div class="fitment-box"><span class="eyebrow">FITMENT CHECK</span>${state.garage.length?`<select id="productVehicle">${garageOptions}</select><div id="fitStatus">${fitBadge(p.fitmentStatus)}</div>`:`<p>Add a vehicle to My Garage before buying this fitment-specific part.</p><a class="secondary-btn" href="#/garage">Add vehicle</a>`}</div>`:`<div class="fitment-box">${fitBadge('FITS')} <small>Universal / no fitment selection required</small></div>`}
      <div class="buy-row"><input id="buyQuantity" type="number" min="1" max="20" value="1"><button class="primary-btn" id="addToBag" ${p.inStock?'':'disabled'}>${p.inStock?'Add to bag':'Sold out'}</button></div><div class="mobile-buy-bar"><div><span>${p.fitmentStatus==='VERIFIED_FIT'?'✓ Verified fit':p.isUniversal?'✓ Universal':'Fitment check'}</span><strong>${money(p.priceCents,p.currency)}</strong></div><button class="primary-btn" id="mobileAddToBag" ${p.inStock?'':'disabled'}>${p.inStock?'Add':'Sold out'}</button></div>
      <div class="product-action-grid"><button class="secondary-btn" id="wishlistProduct">♡ Wishlist</button><button class="secondary-btn" id="compareProduct">＋ Compare</button><button class="secondary-btn" id="priceAlert">↓ Price alert</button><button class="secondary-btn" id="saveBuild">＋ Save to build</button></div>
      ${p.sourceType==='MARKETPLACE'&&seller?`<div class="seller-card"><span class="eyebrow">SOLD BY</span><h3>${esc(sellerName(seller))} ${profile?.verified?'<span class="verified-badge">✓ Verified</span>':''}</h3><p>${esc(profile?.location||p.sellerLocation||'Location not listed')} · ${profile?.ratingCount?`${profile.ratingAverage.toFixed(1)} ★ (${profile.ratingCount})`:'New seller'}</p><div class="seller-reputation-mini" id="sellerReputationMini"><span>Checking seller reputation…</span></div><div class="product-action-grid"><a class="secondary-btn" href="#/seller-profile/${encodeURIComponent(seller.id)}">Seller profile</a>${seller.id!==state.user?.id?'<button class="secondary-btn" id="messageSeller">Message seller</button><button class="secondary-btn" id="makeOffer">Make offer</button>':''}</div></div>`:''}
      <div class="detail-facts"><div><span>Stock</span><strong>${p.sourceType==='MARKETPLACE'?`${p.stockQuantity??0} available`:p.inStock?'Available':'Unavailable'}</strong></div><div><span>Shipping</span><strong id="shippingEstimate" class="shipping-estimate">${p.shippingMinDays!=null?`${p.shippingMinDays}–${p.shippingMaxDays??p.shippingMinDays} days`:'Checking estimate…'}</strong></div><div><span>Returns</span><strong>${p.returnDays!=null?`${p.returnDays} days`:'See policy'}</strong></div><div><span>Warranty</span><strong>${esc(p.warrantyText||'See listing')}</strong></div></div>
      <details open><summary>Specifications</summary><div class="spec-grid">${p.specs?Object.entries(p.specs).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join(''):'<p>No extra specifications listed.</p>'}<div><span>SKU</span><strong>${esc(p.sku)}</strong></div><div><span>Install difficulty</span><strong>${esc(p.installDifficulty||'Not rated')}</strong></div></div></details><details><summary>Full description</summary><p>${esc(p.description)}</p></details>${p.fitments?.length?`<details><summary>Compatible vehicles (${p.fitments.length})</summary><div class="fitment-list">${p.fitments.slice(0,40).map(f=>`<span>${esc(`${f.vehicleVariant.model.make.name} ${f.vehicleVariant.model.name} ${f.vehicleVariant.yearStart}-${f.vehicleVariant.yearEnd} · ${f.vehicleVariant.engineCode}`)}</span>`).join('')}</div></details>`:''}</div></div>
      <section class="section"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">VERIFIED PURCHASES</span><h2>Reviews.</h2></div><span>${p.rating?p.rating.toFixed(1):'—'} / 5</span></div><div class="reviews-grid">${p.reviews?.length?p.reviews.map(r=>`<article class="review-card"><div class="rating-line"><span>${'★'.repeat(r.rating)}</span><small>Verified purchase</small></div><h3>${esc(r.title||'Buyer review')}</h3><p>${esc(r.body||'')}</p>${Array.isArray(r.mediaUrls)&&r.mediaUrls.length?`<div class="review-media">${r.mediaUrls.slice(0,5).map(url=>`<img src="${esc(url)}" alt="Review photo" loading="lazy" decoding="async">`).join('')}</div>`:''}${r.vehicle?`<span class="review-vehicle">Installed for ${esc(reviewVehicleLabel(r.vehicle))}</span>`:''}<small>${esc([r.user.firstName,r.user.lastName].filter(Boolean).join(' ')||'SANDMAN buyer')} · ${fmtDate(r.createdAt)}</small></article>`).join(''):emptyProducts('No reviews yet.')}</div></div></section><section class="section"><div class="section-inner"><div class="section-head"><div><span class="eyebrow">YOU MAY ALSO NEED</span><h2>Complete the build.</h2></div></div><div id="recommendations">${cardSkeletons(4)}</div></div></section>`;
      $$('.gallery-thumbs button').forEach(b=>b.onclick=()=>{$('#mainProductImage').src=b.dataset.image;$$('.gallery-thumbs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');});
      api(`/v2/shipping-estimate/${p.id}`).then(estimate=>{const el=$('#shippingEstimate');if(!el)return;el.textContent=estimate.minDays!=null?`${estimate.minDays}–${estimate.maxDays} days${estimate.shippingCents!=null?` · from ${money(estimate.shippingCents,p.currency)}`:''}`:'Calculated at checkout';}).catch(()=>{const el=$('#shippingEstimate');if(el&&!p.shippingMinDays)el.textContent='Calculated at checkout';});
      if(seller){api(`/community/seller/${encodeURIComponent(seller.id)}`).then(data=>{const rep=data.reputation||{};const el=$('#sellerReputationMini');if(!el)return;const badges=(rep.badges||[]).map(badge=>`<span class="seller-rep-badge">${esc(reputationLabel(badge))}</span>`).join('');const facts=[data.sold!=null?`${data.sold} verified sale${data.sold===1?'':'s'}`:null,rep.shippedOrderRate!=null?`${rep.shippedOrderRate}% shipped`:null,rep.responseTimeHours!=null?`response goal ~${rep.responseTimeHours}h`:null].filter(Boolean).join(' · ');el.innerHTML=`${badges?`<div class="reputation-badges">${badges}</div>`:''}<span>${esc(facts||'New seller')}</span>`;}).catch(()=>{const el=$('#sellerReputationMini');if(el)el.textContent='Seller profile available';});}
      let selectedVariant=primary?.vehicleVariantId;
      $('#productVehicle')?.addEventListener('change',async e=>{selectedVariant=e.target.value;const fit=await api(`/products/${p.id}/fitment/${selectedVariant}`);$('#fitStatus').innerHTML=fitBadge(fit.status);});
      $('#addToBag').onclick=()=>addToCart(p.id,Number($('#buyQuantity').value)||1,p.requiresFitment&&!p.isUniversal?selectedVariant:undefined);
      $('#mobileAddToBag')?.addEventListener('click',()=>addToCart(p.id,Number($('#buyQuantity').value)||1,p.requiresFitment&&!p.isUniversal?selectedVariant:undefined));
      $('#wishlistProduct').onclick=async()=>{if(!requireLogin())return;try{await api(`/experience/wishlist/${p.id}`,{method:'POST'});toast('Saved to wishlist');}catch(e){toast(e.message,'error');}};
      $('#compareProduct').onclick=()=>{if(!state.compare.includes(p.id))state.compare.push(p.id);state.compare=state.compare.slice(-4);toast(state.compare.length>=2?'Ready to compare':'Added to compare'); if(state.compare.length>=2)location.hash=`#/compare?ids=${encodeURIComponent(state.compare.join(','))}`;};
      $('#priceAlert').onclick=async()=>{if(!requireLogin())return;const raw=prompt(`Alert me when ${p.name} drops below (USD):`,(p.priceCents/100*0.9).toFixed(2));if(!raw)return;try{await api('/experience/alerts',{method:'POST',body:JSON.stringify({productId:p.id,type:'PRICE_DROP',targetPriceCents:Math.round(Number(raw)*100)})});toast('Price alert created');}catch(e){toast(e.message,'error');}};
      $('#saveBuild').onclick=async()=>{if(!requireLogin())return;await loadBuilds();if(!state.builds.length){toast('Create a build first');location.hash='#/builds';return;}const choices=state.builds.map((b,i)=>`${i+1}. ${b.name}`).join('\n');const n=Number(prompt(`Save to which build?\n${choices}`));const b=state.builds[n-1];if(!b)return;try{await api(`/builds/${b.id}/items`,{method:'POST',body:JSON.stringify({productId:p.id,quantity:1})});toast(`Saved to ${b.name}`);}catch(e){toast(e.message,'error');}};
      $('#messageSeller')?.addEventListener('click',async()=>{if(!requireLogin())return;const message=prompt('Message the seller:');if(!message)return;try{const out=await api('/community/conversations',{method:'POST',body:JSON.stringify({productId:p.id,message})});toast('Message sent');location.hash=`#/messages?conversation=${out.conversation.id}`;}catch(e){toast(e.message,'error');}});
      $('#makeOffer')?.addEventListener('click',async()=>{if(!requireLogin())return;const raw=prompt(`Your offer in USD (listing is ${money(p.priceCents)}):`);if(!raw)return;const amountCents=Math.round(Number(raw)*100);if(!Number.isFinite(amountCents))return;try{await api('/community/offers',{method:'POST',body:JSON.stringify({productId:p.id,amountCents})});toast('Offer sent');}catch(e){toast(e.message,'error');}});
      const recs=await api(`/experience/products/${p.id}/recommendations`).catch(()=>[]); $('#recommendations').innerHTML=recs.length?`<div class="product-grid">${recs.slice(0,4).map(productCard).join('')}</div>`:emptyProducts('No related parts yet.'); bindCompareButtons($('#recommendations'));
    } catch(e){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Part unavailable.</h1><p>${esc(e.message)}</p></div></section></div>`;}
  }

  async function loadPickerLevel(params = {}) {
    const query = new URLSearchParams();
    if (params.makeId) query.set('makeId', params.makeId);
    if (params.modelId) query.set('modelId', params.modelId);
    if (params.year) query.set('year', String(params.year));
    const suffix = query.toString();
    return api(`/v2/vehicles/picker${suffix ? `?${suffix}` : ''}`);
  }

  function variantDisplayName(variant) {
    const make = variant?.model?.make?.name || '';
    const model = variant?.model?.name || '';
    const years = variant ? `${variant.yearStart}${variant.yearEnd !== variant.yearStart ? `–${variant.yearEnd}` : ''}` : '';
    return [years, make, model, variant?.trim, variant?.engineCode].filter(Boolean).join(' · ');
  }

  async function wireVehiclePicker(prefix, onVariants) {
    const make = $(`#${prefix}Make`), model = $(`#${prefix}Model`), year = $(`#${prefix}Year`), variant = $(`#${prefix}Variant`);
    if (!make || !model || !year) return;
    const resetSelect = (el, label) => { if (el) { el.innerHTML = `<option value="">${esc(label)}</option>`; el.disabled = true; } };
    const setLoading = (el, label = 'Loading…') => { if (el) { el.innerHTML = `<option value="">${esc(label)}</option>`; el.disabled = true; } };
    const loadMakes = async () => {
      setLoading(make);
      const data = await loadPickerLevel();
      make.innerHTML = `<option value="">Choose make</option>${(data.makes || []).map(row => `<option value="${esc(row.id)}">${esc(row.name)}</option>`).join('')}`;
      make.disabled = false;
    };
    make.onchange = async () => {
      resetSelect(model, 'Choose model'); resetSelect(year, 'Choose year'); resetSelect(variant, 'Choose variant');
      if (!make.value) { onVariants?.([]); return; }
      setLoading(model);
      try {
        const data = await loadPickerLevel({ makeId: make.value });
        model.innerHTML = `<option value="">Choose model</option>${(data.models || []).map(row => `<option value="${esc(row.id)}">${esc(row.name)}</option>`).join('')}`;
        model.disabled = false;
      } catch (error) { resetSelect(model, 'Could not load models'); toast(error.message, 'error'); }
      onVariants?.([]);
    };
    model.onchange = async () => {
      resetSelect(year, 'Choose year'); resetSelect(variant, 'Choose variant');
      if (!model.value) { onVariants?.([]); return; }
      setLoading(year);
      try {
        const data = await loadPickerLevel({ makeId: make.value, modelId: model.value });
        year.innerHTML = `<option value="">Choose year</option>${(data.years || []).map(value => `<option value="${value}">${value}</option>`).join('')}`;
        year.disabled = false;
      } catch (error) { resetSelect(year, 'Could not load years'); toast(error.message, 'error'); }
      onVariants?.([]);
    };
    year.onchange = async () => {
      resetSelect(variant, 'Choose variant');
      if (!year.value) { onVariants?.([]); return; }
      if (variant) setLoading(variant, 'Loading variants…');
      try {
        const data = await loadPickerLevel({ makeId: make.value, modelId: model.value, year: Number(year.value) });
        const variants = data.variants || [];
        if (variant) {
          variant.innerHTML = `<option value="">Choose exact engine / variant</option>${variants.map(row => `<option value="${esc(row.id)}">${esc([row.trim, row.engineCode, row.engineName].filter(Boolean).join(' · '))}</option>`).join('')}`;
          variant.disabled = false;
        }
        onVariants?.(variants, Number(year.value));
      } catch (error) { resetSelect(variant, 'Could not load variants'); onVariants?.([]); toast(error.message, 'error'); }
    };
    await loadMakes();
  }

  async function renderVehicleFinder() {
    setPageMeta('Vehicle Finder — SANDMAN', 'Choose your exact vehicle and engine before shopping verified-fitment automotive parts.', '/vehicles');
    app.innerHTML = `<div class="v2-tool-page"><section class="v2-tool-hero"><span class="eyebrow">VEHICLE FINDER / VERIFIED FITMENT</span><h1>Choose the exact car.</h1><p>Pick make, model, year and engine variant. SANDMAN only shows verified or catalogue-backed fitment as a confirmed match.</p></section><section class="v2-tool-card"><span class="eyebrow">CATALOGUE PICKER</span><h2>Find your vehicle</h2><div class="vehicle-picker-grid"><label>Make<select id="vfMake"><option>Loading…</option></select></label><label>Model<select id="vfModel" disabled><option>Choose model</option></select></label><label>Year<select id="vfYear" disabled><option>Choose year</option></select></label></div><div id="vfResults" class="v2-results"><p class="form-note">Choose a year to see the available engine and chassis variants.</p></div></section><section class="v2-tool-card"><span class="eyebrow">VIN / OPTIONAL</span><h2>Start from a VIN</h2><form id="finderVinForm" class="vin-panel"><div class="vin-copy"><p>A VIN decode is a starting point, not automatic proof of fitment. Confirm the exact SANDMAN catalogue variant before shopping.</p></div><label>17-character VIN<input name="vin" minlength="17" maxlength="17" pattern="[A-HJ-NPR-Z0-9]{17}" autocomplete="off" required></label><button class="primary-btn">Decode VIN</button><div id="finderVinResult" class="vin-result"></div></form></section><div class="v2-tool-foot"><a class="secondary-btn" href="/requests">Can't find your vehicle? Request it</a></div></div>`;
    const result = $('#vfResults');
    const renderVariants = (variants, year) => {
      result.innerHTML = variants.length ? `<div class="variant-grid">${variants.map(v => `<article class="variant-card"><span class="eyebrow">${esc(year || v.yearStart)} / ${esc(v.chassisCode || 'CATALOGUE')}</span><h3>${esc(v.engineCode || v.engineName || 'Variant')}</h3><p>${esc([v.model?.make?.name, v.model?.name, v.trim, v.engineName].filter(Boolean).join(' · '))}</p><div class="variant-meta">${v.displacementCc ? `<span>${(v.displacementCc / 1000).toFixed(1)}L</span>` : ''}${v.aspiration ? `<span>${esc(v.aspiration)}</span>` : ''}${v.drivetrain ? `<span>${esc(v.drivetrain)}</span>` : ''}${v.transmission ? `<span>${esc(v.transmission)}</span>` : ''}</div><div class="variant-actions"><a class="primary-btn" href="/shop?vehicleVariantId=${encodeURIComponent(v.id)}">Shop compatible parts</a><button class="secondary-btn" data-save-variant="${esc(v.id)}" data-year="${year || v.yearStart}">Add to My Garage</button></div></article>`).join('')}</div>` : '<p class="form-note">No catalogue variants match that year yet. You can request the vehicle below.</p>';
      $$('[data-save-variant]', result).forEach(button => button.onclick = async () => {
        if (!requireLogin('Log in to save this vehicle to My Garage.')) return;
        try {
          await loadGarage();
          await api('/garage', { method:'POST', body:JSON.stringify({ vehicleVariantId:button.dataset.saveVariant, year:Number(button.dataset.year), isPrimary:state.garage.length === 0 }) });
          toast('Vehicle added to My Garage');
        } catch (error) { toast(error.message, 'error'); }
      });
    };
    await wireVehiclePicker('vf', renderVariants);
    $('#finderVinForm').onsubmit = async event => {
      event.preventDefault();
      const vin = String(new FormData(event.currentTarget).get('vin') || '').trim().toUpperCase();
      const target = $('#finderVinResult');
      target.innerHTML = '<p>Decoding VIN…</p>';
      try {
        const data = await api('/v2/vin/decode', { method:'POST', body:JSON.stringify({ vin }) });
        const d = data.decoded || {}, candidates = data.candidates || [];
        target.innerHTML = `<div class="vin-decoded"><strong>${esc([d.modelYear,d.make,d.model,d.trim].filter(Boolean).join(' ') || 'VIN decoded')}</strong><small>${esc(data.note || d.errorText || 'Confirm the exact vehicle below.')}</small></div>${candidates.length ? `<div class="variant-grid">${candidates.map(v => `<article class="variant-card"><span class="eyebrow">VIN MATCH ${Number(v.score || 0)}%</span><h3>${esc(v.engineCode || 'Variant')}</h3><p>${esc([v.model?.make?.name,v.model?.name,v.engineName].filter(Boolean).join(' · '))}</p><div class="variant-actions"><a class="primary-btn" href="/shop?vehicleVariantId=${encodeURIComponent(v.id)}">Shop this variant</a>${state.token && d.modelYear ? `<button class="secondary-btn" data-vin-save="${esc(v.id)}">Add to Garage</button>` : ''}</div></article>`).join('')}</div>` : '<p>No matching SANDMAN catalogue variant yet. Submit a vehicle request instead.</p>'}`;
        $$('[data-vin-save]', target).forEach(button => button.onclick = async () => { try { await loadGarage(); await api('/garage',{method:'POST',body:JSON.stringify({vehicleVariantId:button.dataset.vinSave,year:Number(d.modelYear),vin,isPrimary:state.garage.length===0})}); toast('VIN vehicle added to My Garage'); } catch(error){ toast(error.message,'error'); } });
      } catch (error) { target.innerHTML = `<p class="danger-copy">${esc(error.message)}</p>`; }
    };
  }

  async function renderAdvisor() {
    setPageMeta('Build Advisor — SANDMAN', 'Plan an automotive build using SANDMAN catalogue fitment and product availability.', '/build-advisor');
    app.innerHTML = `<div class="v2-tool-page"><section class="v2-tool-hero"><span class="eyebrow">BUILD ADVISOR / PLANNING</span><h1>Plan the build.</h1><p>Select an exact vehicle, goal and budget. Recommendations are planning guidance only and keep SANDMAN's fitment evidence rules intact.</p></section><section class="v2-tool-card"><form id="advisorForm" class="advisor-form"><label>Make<select id="advMake"><option>Loading…</option></select></label><label>Model<select id="advModel" disabled><option>Choose model</option></select></label><label>Year<select id="advYear" disabled><option>Choose year</option></select></label><label>Exact engine / variant<select id="advVariant" name="vehicleVariantId" disabled required><option>Choose variant</option></select></label><label>Goal<select name="goal"><option value="DAILY">Daily</option><option value="RELIABILITY">Reliability</option><option value="STREET" selected>Street</option><option value="TRACK">Track</option></select></label><label>Target power (hp)<input name="targetPowerHp" type="number" min="50" max="5000" placeholder="e.g. 550"></label><label>Budget (USD)<input name="budget" type="number" min="1" step="1" placeholder="e.g. 5000"></label><button class="primary-btn" type="submit">Build recommendation</button><p class="form-note">Recommendations never replace a qualified mechanic, tuner or vehicle-specific engineering check.</p></form></section><div id="advisorResults"></div></div>`;
    await wireVehiclePicker('adv');
    $('#advisorForm').onsubmit = async event => {
      event.preventDefault();
      const f = new FormData(event.currentTarget), target = $('#advisorResults');
      const vehicleVariantId = String(f.get('vehicleVariantId') || '');
      if (!vehicleVariantId) return toast('Choose the exact engine / variant first', 'error');
      const targetPowerHp = Number(f.get('targetPowerHp')) || undefined;
      const budget = Number(f.get('budget'));
      target.innerHTML = '<section class="v2-tool-card"><p>Building recommendations…</p></section>';
      try {
        const data = await api('/v2/build-advisor', { method:'POST', body:JSON.stringify({ vehicleVariantId, goal:f.get('goal'), targetPowerHp, budgetCents:budget > 0 ? Math.round(budget * 100) : undefined }) });
        const vehicle = data.vehicle || {};
        const groups = (data.recommendations || []).filter(group => group.products?.length);
        target.innerHTML = `<section class="advisor-summary"><span class="eyebrow">ADVISOR RESULT / ${esc(data.goal)}</span><h2>${esc(variantDisplayName(vehicle))}</h2><p>${data.targetPowerHp ? `${data.targetPowerHp} hp target · ` : ''}${data.budgetCents ? `${money(data.budgetCents)} budget · ` : ''}${money(data.suggestedCartCents)} across suggested catalogue parts.</p>${data.budgetDeltaCents != null ? `<p class="${data.budgetDeltaCents < 0 ? 'danger-copy' : ''}">${data.budgetDeltaCents >= 0 ? `${money(data.budgetDeltaCents)} remains in budget.` : `${money(Math.abs(data.budgetDeltaCents))} above budget.`}</p>` : ''}</section>${groups.length ? groups.map(group => `<section class="advisor-group"><span class="eyebrow">${esc(group.category)}</span><h3>${esc(titleCase(group.category))}</h3><div class="product-grid">${group.products.map(p => `<a class="advisor-product" href="/products/${encodeURIComponent(p.slug)}"><strong>${esc(p.name)}</strong><span>${money(p.priceCents,p.currency)}</span><small>${p.fitment?.verified ? '✓ Verified fitment' : p.fitment?.status ? esc(titleCase(p.fitment.status)) : 'Compatibility record'} · ${p.availability?.inStock ? 'In stock' : 'Check availability'}</small></a>`).join('')}</div></section>`).join('') : '<section class="v2-tool-card"><p>No catalogue recommendations match this vehicle and goal yet.</p></section>'}<div class="advisor-warning">${esc(data.safetyNote || 'Vehicle modifications require professional validation.')}</div>`;
      } catch (error) { target.innerHTML = `<section class="v2-tool-card"><p class="danger-copy">${esc(error.message)}</p></section>`; }
    };
  }

  async function renderRequests() {
    setPageMeta('Request a Part or Vehicle — SANDMAN', 'Ask SANDMAN to source a missing automotive part or add a missing vehicle to the catalogue.', '/requests');
    const emailField = state.token ? '' : '<label>Email<input name="email" type="email" required autocomplete="email"></label>';
    app.innerHTML = `<div class="v2-tool-page"><section class="v2-tool-hero"><span class="eyebrow">SOURCING DESK / REQUESTS</span><h1>Can't find it?</h1><p>Send the SANDMAN sourcing desk the missing part or vehicle. Give enough detail for a dealer or supplier match without making unsupported fitment claims.</p></section><div class="request-grid"><section class="v2-tool-card"><span class="eyebrow">REQUEST A PART</span><h2>Source a part</h2><form id="partRequestForm" class="market-form">${emailField}<label>Part name<input name="partName" minlength="2" maxlength="180" required placeholder="B58 charge pipe"></label><label>OEM / manufacturer number<input name="oemNumber" maxlength="120"></label><label>Budget USD<input name="budget" type="number" min="1" step="1"></label><label>Notes<textarea name="notes" maxlength="3000" rows="5" placeholder="Vehicle, engine code, condition, brand preference…"></textarea></label><button class="primary-btn">Submit part request</button></form></section><section class="v2-tool-card"><span class="eyebrow">REQUEST A VEHICLE</span><h2>Add a vehicle</h2><form id="vehicleRequestForm" class="market-form">${emailField}<div class="field-row"><label>Make<input name="make" maxlength="80" required></label><label>Model<input name="model" maxlength="120" required></label></div><div class="field-row"><label>Year<input name="year" type="number" min="1886" max="2200"></label><label>Trim<input name="trim" maxlength="120"></label></div><label>Engine code<input name="engineCode" maxlength="80"></label><label>Notes<textarea name="notes" maxlength="2000" rows="5"></textarea></label><button class="primary-btn">Submit vehicle request</button></form></section></div>${state.token ? '<section class="v2-tool-card" id="myRequests"><span class="eyebrow">MY REQUESTS</span><h2>Recent requests</h2><div id="myRequestRows"><p>Loading…</p></div></section>' : '<div class="v2-tool-foot"><button class="secondary-btn" id="requestLogin">Log in to track requests</button></div>'}</div>`;
    const submit = async (form, endpoint, payload) => {
      const button = form.querySelector('button[type="submit"]');
      button.disabled = true;
      try { await api(endpoint, { method:'POST', body:JSON.stringify(payload) }); form.reset(); toast('Request submitted to SANDMAN'); if (state.token) await loadMine(); }
      catch (error) { toast(error.message, 'error'); }
      finally { button.disabled = false; }
    };
    $('#partRequestForm').onsubmit = event => { event.preventDefault(); const f = new FormData(event.currentTarget), budget = Number(f.get('budget')); submit(event.currentTarget, '/v2/requests/part', { email:f.get('email') || undefined, partName:f.get('partName'), oemNumber:f.get('oemNumber') || undefined, notes:f.get('notes') || undefined, budgetCents:budget > 0 ? Math.round(budget * 100) : undefined }); };
    $('#vehicleRequestForm').onsubmit = event => { event.preventDefault(); const f = new FormData(event.currentTarget), year = Number(f.get('year')); submit(event.currentTarget, '/v2/requests/vehicle', { email:f.get('email') || undefined, make:f.get('make'), model:f.get('model'), year:year || undefined, trim:f.get('trim') || undefined, engineCode:f.get('engineCode') || undefined, notes:f.get('notes') || undefined }); };
    async function loadMine() {
      const target = $('#myRequestRows'); if (!target) return;
      try {
        const data = await api('/v2/requests/mine');
        const rows = [ ...(data.partRequests || []).map(row => ({ title:row.partName, kind:'Part', status:row.status, date:row.createdAt })), ...(data.vehicleRequests || []).map(row => ({ title:[row.year,row.make,row.model,row.trim].filter(Boolean).join(' '), kind:'Vehicle', status:row.status, date:row.createdAt })) ].sort((a,b) => new Date(b.date) - new Date(a.date));
        target.innerHTML = rows.length ? rows.slice(0,30).map(row => `<div class="request-row"><strong>${esc(row.title)}</strong><span>${esc(row.kind)}</span><small>${esc(titleCase(row.status))} · ${fmtDate(row.date)}</small></div>`).join('') : '<p class="form-note">No requests submitted yet.</p>';
      } catch (error) { target.innerHTML = `<p class="danger-copy">${esc(error.message)}</p>`; }
    }
    $('#requestLogin')?.addEventListener('click', () => openAuth('login'));
    if (state.token) await loadMine();
  }

  async function renderGarage() {
    if(!state.token)return renderAccountRequired('My Garage','Log in to save cars and check fitment.'); await loadGarage();
    app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">MY GARAGE / FITMENT</span><h1>Your cars.</h1><p>Save multiple vehicles. Your primary car powers fitment badges across SANDMAN.</p></div></div><div class="garage-grid">${state.garage.length?state.garage.map(g=>`<article class="garage-card ${g.isPrimary?'primary':''}" data-garage-id="${g.id}"><span class="eyebrow">${g.isPrimary?'PRIMARY VEHICLE':'GARAGE VEHICLE'}</span><h2>${esc(vehicleName(g))}</h2><p>${esc(g.nickname||g.vehicleVariant.engineName)} ${g.vin?`· VIN ${esc(g.vin)}`:''}</p><div class="garage-actions">${!g.isPrimary?'<button class="secondary-btn" data-primary>Make primary</button>':''}<a class="primary-btn" href="#/shop?vehicleVariantId=${encodeURIComponent(g.vehicleVariantId)}">Shop parts</a><button class="text-link danger-text" data-delete>Remove</button></div></article>`).join(''):emptyProducts('No vehicles saved yet.')}</div><section class="garage-add"><span class="eyebrow">ADD VEHICLE</span><h2>Decode a VIN or search the catalogue.</h2><form id="vinLookupForm" class="vin-panel"><div class="vin-copy"><span class="eyebrow">VIN LOOKUP / NHTSA VPIC</span><h3>17 characters. One faster starting point.</h3><p>SANDMAN decodes the VIN, then compares the result with the SANDMAN vehicle catalogue. You confirm the exact variant before fitment is used.</p></div><label>VIN<input name="vin" minlength="17" maxlength="17" pattern="[A-HJ-NPR-Z0-9]{17}" placeholder="WBA…" required></label><button class="primary-btn">Decode VIN</button><div id="vinResult" class="vin-result"></div></form><span class="eyebrow">OR SEARCH</span><form id="vehicleSearchForm" class="inline-search"><input name="q" minlength="2" placeholder="BMW M340i, B58, EA888, 2JZ..." required><button class="primary-btn">Search</button></form><div id="vehicleResults"></div></section></div>`;
    $$('[data-garage-id]').forEach(card=>{card.querySelector('[data-primary]')?.addEventListener('click',async()=>{await api(`/garage/${card.dataset.garageId}/primary`,{method:'PATCH'});toast('Primary vehicle updated');renderGarage();});card.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!confirm('Remove this vehicle from your garage?'))return;await api(`/garage/${card.dataset.garageId}`,{method:'DELETE'});toast('Vehicle removed');renderGarage();});});
    $('#vinLookupForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;const vin=String(new FormData(form).get('vin')||'').trim().toUpperCase();const result=$('#vinResult');result.innerHTML='<p>Decoding VIN…</p>';try{const data=await api('/v2/vin/decode',{method:'POST',body:JSON.stringify({vin})});const d=data.decoded;const candidates=data.candidates||[];result.innerHTML=`<div class="vin-decoded"><strong>${esc([d.modelYear,d.make,d.model,d.trim].filter(Boolean).join(' ')||'VIN decoded')}</strong><small>${esc([d.engineModel,d.displacementL?`${d.displacementL}L`:null,d.driveType].filter(Boolean).join(' · ')||d.errorText||'Vehicle details returned by NHTSA')}</small></div>${candidates.length?`<div class="vehicle-results">${candidates.map(c=>`<article><div><strong>${esc(`${c.model.make.name} ${c.model.name}`)} ${data.matchedVariant?.id===c.id?'<span class="verified-badge">HIGH CONFIDENCE</span>':''}</strong><span>${c.yearStart}–${c.yearEnd} · ${esc(c.engineCode)} · match ${c.score}%</span></div><button class="secondary-btn" data-add-vin-variant="${esc(c.id)}">Confirm & add</button></article>`).join('')}</div>`:'<p>No matching SANDMAN catalogue variant yet. Use catalogue search below or request the vehicle.</p>'}`;$$('[data-add-vin-variant]',result).forEach(button=>button.onclick=async()=>{const year=Number(d.modelYear);if(!year)return toast('VIN did not return a usable model year','error');try{await api('/garage',{method:'POST',body:JSON.stringify({vehicleVariantId:button.dataset.addVinVariant,year,vin,isPrimary:state.garage.length===0})});toast('VIN vehicle added to My Garage');renderGarage();}catch(error){toast(error.message,'error');}});}catch(error){result.innerHTML=`<p>${esc(error.message)}</p>`;}};
    $('#vehicleSearchForm').onsubmit=async e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('q');const rows=await api(`/vehicles/search?q=${encodeURIComponent(q)}`);$('#vehicleResults').innerHTML=rows.length?`<div class="vehicle-results">${rows.map(v=>`<article><div><strong>${esc(`${v.model.make.name} ${v.model.name}`)}</strong><span>${v.yearStart}–${v.yearEnd} · ${esc(v.engineCode)} · ${esc(v.engineName)}</span></div><button class="secondary-btn" data-add-variant="${v.id}" data-year-start="${v.yearStart}" data-year-end="${v.yearEnd}">Add</button></article>`).join('')}</div>`:emptyProducts('No matching vehicle variants.');$$('[data-add-variant]').forEach(b=>b.onclick=async()=>{const year=Number(prompt(`Vehicle year (${b.dataset.yearStart}–${b.dataset.yearEnd}):`,b.dataset.yearEnd));if(!year)return;try{await api('/garage',{method:'POST',body:JSON.stringify({vehicleVariantId:b.dataset.addVariant,year,isPrimary:state.garage.length===0})});toast('Added to My Garage');renderGarage();}catch(err){toast(err.message,'error');}});};
  }

  async function renderBuilds() {
    if(!state.token)return renderAccountRequired('SANDMAN Builds','Log in to create and save complete parts builds.'); await Promise.all([loadBuilds(),loadGarage()]);
    app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">SANDMAN BUILDS</span><h1>Build the setup.</h1><p>Create a target, collect compatible parts and see the total cost.</p></div><button class="primary-btn" id="newBuildButton">New build</button></div><div class="build-grid">${state.builds.length?state.builds.map(b=>`<a class="build-card" href="#/build/${b.id}"><span class="eyebrow">${b.isPublic?'PUBLIC BUILD':'PRIVATE BUILD'}</span><h2>${esc(b.name)}</h2><p>${b.garageVehicle?esc(vehicleName(b.garageVehicle)):'No vehicle selected'}</p><div class="build-stats"><span>${b._count?.items||0} parts</span><span>${b.targetPowerHp?`${b.targetPowerHp} hp target`:'No power target'}</span><span>${b.budgetCents?`${money(b.budgetCents)} budget`:'No budget'}</span></div></a>`).join(''):emptyProducts('Create your first build.')}</div></div>`;
    $('#newBuildButton').onclick=async()=>{const name=prompt('Build name:','My B58 Build');if(!name)return;let garageVehicleId;if(state.garage.length){const choices=state.garage.map((g,i)=>`${i+1}. ${vehicleName(g)}`).join('\n');const n=Number(prompt(`Choose a vehicle (0 for none):\n${choices}`));if(n>0)garageVehicleId=state.garage[n-1]?.id;}const goal=(prompt('Build goal (DAILY / RELIABILITY / STREET / TRACK):','STREET')||'STREET').trim().toUpperCase();const hp=Number(prompt('Target horsepower (optional):','550'))||undefined;const torque=Number(prompt('Target torque Nm (optional):',''))||undefined;const budget=Number(prompt('Budget in USD (optional):','5000'));try{const b=await api('/builds',{method:'POST',body:JSON.stringify({name,garageVehicleId,goal,targetPowerHp:hp,targetTorqueNm:torque,budgetCents:budget?Math.round(budget*100):undefined})});toast('Build created');location.hash=`#/build/${b.id}`;}catch(e){toast(e.message,'error');}};
  }

  async function renderBuild(id) {
    if(!state.token)return renderAccountRequired('Build','Log in to open your build.');
    try{const b=await api(`/builds/${id}`);const vehicle=b.garageVehicle?vehicleName(b.garageVehicle):b.vehicleVariant?`${b.vehicleVariant.model.make.name} ${b.vehicleVariant.model.name} · ${b.vehicleVariant.engineCode}`:'No vehicle selected';app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">SANDMAN BUILD / ${b.isPublic?'PUBLIC':'PRIVATE'}</span><h1>${esc(b.name)}</h1><p>${esc(vehicle)}${b.goal?` · ${esc(titleCase(b.goal))}`:''}${b.targetPowerHp?` · ${b.targetPowerHp} hp target`:''}${b.targetTorqueNm?` · ${b.targetTorqueNm} Nm target`:''}</p></div><div><button class="secondary-btn" id="editBuild">Edit</button><button class="secondary-btn" id="shareBuild">${b.isPublic?'Copy share link':'Make public'}</button></div></div><div class="build-summary"><div><span>Total parts</span><strong>${money(b.totalCents)}</strong></div><div><span>Budget</span><strong>${b.budgetCents?money(b.budgetCents):'Not set'}</strong></div><div><span>Remaining</span><strong>${b.budgetRemainingCents==null?'—':money(b.budgetRemainingCents)}</strong></div><div><span>Compatibility</span><strong>${b.incompatible?`${b.incompatible} conflict${b.incompatible===1?'':'s'}`:b.unconfirmed?`${b.unconfirmed} unconfirmed`:'✓ Clear'}</strong></div></div><div class="build-items">${b.items.length?b.items.map(i=>`<article class="build-item" data-item-id="${i.id}">${imageOf(i.product)?`<img src="${esc(imageOf(i.product))}" alt="">`:''}<div><span class="eyebrow">${esc(i.product.category?.name||'PART')}</span><h3><a href="#/product/${encodeURIComponent(i.product.slug)}">${esc(i.product.name)}</a></h3>${fitBadge(i.fitmentStatus)}<p>Qty ${i.quantity} · ${money(i.lineTotalCents)}</p></div><button class="text-link danger-text" data-remove-build-item>Remove</button></article>`).join(''):emptyProducts('No parts saved to this build yet.')}</div><div class="build-add-panel"><h2>Add parts</h2><p>Shop SANDMAN and use “Save to build” from any product page.</p><a class="primary-btn" href="#/shop${b.garageVehicle?`?vehicleVariantId=${encodeURIComponent(b.garageVehicle.vehicleVariantId)}`:''}">Find compatible parts</a></div></div>`;$$('[data-remove-build-item]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-item-id]');await api(`/builds/${b.id}/items/${row.dataset.itemId}`,{method:'DELETE'});toast('Part removed');renderBuild(id);});$('#editBuild').onclick=async()=>{const name=prompt('Build name:',b.name);if(!name)return;const goal=(prompt('Build goal:',b.goal||'STREET')||'').trim().toUpperCase()||null;const hp=Number(prompt('Target horsepower:',b.targetPowerHp||''))||null;const torque=Number(prompt('Target torque Nm:',b.targetTorqueNm||''))||null;const budget=Number(prompt('Budget USD:',b.budgetCents?b.budgetCents/100:''));await api(`/builds/${b.id}`,{method:'PATCH',body:JSON.stringify({name,goal,targetPowerHp:hp,targetTorqueNm:torque,budgetCents:budget?Math.round(budget*100):null})});renderBuild(id);};$('#shareBuild').onclick=async()=>{if(!b.isPublic){await api(`/builds/${b.id}`,{method:'PATCH',body:JSON.stringify({isPublic:true})});toast('Build is now public');renderBuild(id);return;}navigator.clipboard?.writeText(`${location.origin}/public-builds/${b.id}`);toast('Share link copied');};}catch(e){app.innerHTML=emptyProducts(e.message);}
  }
  async function renderPublicBuild(id){try{const b=await api(`/builds/public/${id}`);app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">PUBLIC SANDMAN BUILD</span><h1>${esc(b.name)}</h1><p>${b.targetPowerHp?`${b.targetPowerHp} hp target · `:''}${money(b.totalCents)} in parts</p></div></div><div class="build-items">${b.items.map(i=>`<article class="build-item">${imageOf(i.product)?`<img src="${esc(imageOf(i.product))}" alt="">`:''}<div><h3><a href="#/product/${encodeURIComponent(i.product.slug)}">${esc(i.product.name)}</a></h3>${fitBadge(i.fitmentStatus)}<p>${money(i.lineTotalCents)}</p></div></article>`).join('')}</div></div>`;}catch(e){app.innerHTML=emptyProducts(e.message);}}

  async function renderCompare(params){const ids=(params.get('ids')||state.compare.join(',')).split(',').filter(Boolean).slice(0,4);state.compare=ids;if(ids.length<2){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Compare parts.</h1><p>Add at least two products using the Compare button.</p><a class="primary-btn" href="#/shop">Shop parts</a></div></section></div>`;return;}try{const ps=await api(`/experience/compare?ids=${encodeURIComponent(ids.join(','))}`);const rows=[['Price',p=>money(p.priceCents,p.currency)],['Brand',p=>p.brand||'—'],['Condition',p=>titleCase(p.condition)],['Stock',p=>p.inStock?'In stock':'Out of stock'],['Rating',p=>p.rating?`${p.rating.toFixed(1)} / 5`:'—'],['Warranty',p=>p.warrantyText||'—'],['Returns',p=>p.returnDays!=null?`${p.returnDays} days`:'—'],['Install',p=>p.installDifficulty||'—'],['SKU / MPN',p=>p.manufacturerPn||p.sku]];app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">COMPARE / UP TO 4</span><h1>Side by side.</h1></div><button class="secondary-btn" id="clearCompare">Clear</button></div><div class="compare-table"><div class="compare-row compare-head"><div>Part</div>${ps.map(p=>`<div>${imageOf(p)?`<img src="${esc(imageOf(p))}" alt="">`:''}<a href="#/product/${encodeURIComponent(p.slug)}"><strong>${esc(p.name)}</strong></a></div>`).join('')}</div>${rows.map(([label,fn])=>`<div class="compare-row"><div>${label}</div>${ps.map(p=>`<div>${esc(fn(p))}</div>`).join('')}</div>`).join('')}</div></div>`;$('#clearCompare').onclick=()=>{state.compare=[];location.hash='#/shop';};}catch(e){app.innerHTML=emptyProducts(e.message);}}

  async function renderWishlist(){if(!state.token)return renderAccountRequired('Wishlist','Log in to save parts.');const rows=await api('/experience/wishlist').catch(()=>[]);app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">WISHLIST</span><h1>Saved parts.</h1></div></div>${rows.length?`<div class="product-grid">${rows.map(r=>productCard(r.product)).join('')}</div>`:emptyProducts('Save products from any product page.')}</div>`;bindCompareButtons(app);}

  async function renderMessages(params){if(!state.token)return renderAccountRequired('Messages','Log in to message marketplace sellers.');const rows=await api('/community/conversations').catch(()=>[]);const active=params.get('conversation')||rows[0]?.id;app.innerHTML=`<div class="messages-page"><aside class="conversation-list"><span class="eyebrow">MESSAGES</span>${rows.length?rows.map(c=>`<button class="conversation-link ${c.id===active?'active':''}" data-conversation="${c.id}"><strong>${esc(c.product.name)}</strong><span>${esc(c.messages?.[0]?.body||'No messages')}</span></button>`).join(''):emptyProducts('No conversations yet.')}</aside><section class="message-thread" id="messageThread"><div class="empty-state"><p>Select a conversation.</p></div></section></div>`;const open=async id=>{const c=rows.find(x=>x.id===id);if(!c)return;const msgs=await api(`/community/conversations/${id}/messages`);const other=state.user.id===c.buyer.id?c.seller:c.buyer;$('#messageThread').innerHTML=`<div class="thread-head"><div><span class="eyebrow">${esc(c.product.name)}</span><h2>${esc([other.firstName,other.lastName].filter(Boolean).join(' ')||'Seller')}</h2></div><a class="secondary-btn" href="#/product/${encodeURIComponent(c.product.slug)}">View part</a></div><div class="messages-list" id="messagesList">${msgs.map(m=>`<div class="message-bubble ${m.senderId===state.user.id?'mine':''}"><p>${esc(m.body)}</p><small>${new Date(m.createdAt).toLocaleString()}</small></div>`).join('')}</div><form id="messageReply" class="message-reply"><textarea name="message" rows="2" maxlength="2000" placeholder="Write a message…" required></textarea><button class="primary-btn">Send</button></form>`;$('#messageReply').onsubmit=async e=>{e.preventDefault();const message=new FormData(e.currentTarget).get('message');await api(`/community/conversations/${id}/messages`,{method:'POST',body:JSON.stringify({message})});open(id);};};$$('[data-conversation]').forEach(b=>b.onclick=()=>{location.hash=`#/messages?conversation=${b.dataset.conversation}`;});if(active)await open(active);}

  async function renderSellerProfile(id){
    try{
      const [data,reviews,followStatus]=await Promise.all([api(`/community/seller/${id}`),api(`/reviews/sellers/${id}`),api(`/social/profiles/${id}/follow-status`).catch(()=>({following:false,blocked:false}))]);
      const s=data.seller,p=s.sellerProfile,rep=data.reputation||{};
      const badges=rep.badges||[];
      setPageMeta(`${p?.storeName||sellerName(s)} — SANDMAN Seller`, p?.bio||'Independent SANDMAN marketplace seller.', `/sellers/${encodeURIComponent(id)}`);
      const canFollow=state.token&&state.user?.id!==id&&!followStatus.blocked;
      app.innerHTML=`<div class="seller-profile-page"><section class="seller-profile-hero">${s.avatarUrl?`<img class="seller-profile-avatar" src="${esc(s.avatarUrl)}" alt="">`:''}<span class="eyebrow">SANDMAN SELLER</span><h1>${esc(p?.storeName||s.displayName||sellerName(s))}</h1>${s.username?`<a class="profile-handle" href="/profile/${encodeURIComponent(s.username)}">@${esc(s.username)}</a>`:''}${badges.length?`<div class="reputation-badges">${badges.map(b=>`<span class="reputation-badge ${b==='VERIFIED'?'verified':''}">${esc(reputationLabel(b))}</span>`).join('')}</div>`:''}<p>${esc(p?.bio||'Independent SANDMAN marketplace seller.')}</p><div class="profile-action-row">${canFollow?`<button class="${followStatus.following?'secondary-btn':'primary-btn'}" id="sellerFollowButton">${followStatus.following?'Following ✓':'Follow'}</button>`:''}${state.token&&state.user?.id!==id?`<button class="ghost-btn" id="sellerReportButton">Report</button>`:''}</div><div class="seller-trust-grid"><div><span>Seller rating</span><strong>${reviews.average?`${reviews.average.toFixed(1)} / 5`:'New seller'}</strong></div><div><span>Verified sales</span><strong>${data.sold}</strong></div><div><span>Shipment rate</span><strong>${rep.shippedOrderRate!=null?`${rep.shippedOrderRate}%`:'—'}</strong></div><div><span>Response goal</span><strong>${rep.responseTimeHours!=null?`~${rep.responseTimeHours}h`:'Not listed'}</strong></div></div><div class="seller-metrics"><span><strong>${reviews.reviewCount}</strong> reviews</span><span><strong>${rep.activeListings??data.listings.length}</strong> active listings</span><span><strong>${fmtDate(s.createdAt)}</strong> joined</span></div></section><section class="section"><div class="section-inner"><div class="section-head"><h2>Active listings.</h2></div>${data.listings.length?`<div class="product-grid">${data.listings.map(productCard).join('')}</div>`:emptyProducts('No active listings.')}</div></section><section class="section"><div class="section-inner"><div class="section-head"><h2>Seller reviews.</h2></div><div class="reviews-grid">${reviews.reviews.length?reviews.reviews.map(r=>`<article class="review-card"><div class="rating-line">${'★'.repeat(r.rating)}</div><p>${esc(r.body||'')}</p><small>Verified marketplace purchase · ${fmtDate(r.createdAt)}</small></article>`).join(''):emptyProducts('No seller reviews yet.')}</div></div></section></div>`;
      $('#sellerFollowButton')?.addEventListener('click',async()=>{try{if(followStatus.following)await api(`/social/profiles/${id}/follow`,{method:'DELETE'});else await api(`/social/profiles/${id}/follow`,{method:'POST'});toast(followStatus.following?'Unfollowed':'Following — you will get listing and post alerts');renderSellerProfile(id);}catch(error){toast(error.message,'error');}});
      $('#sellerReportButton')?.addEventListener('click',()=>openReportComposer('USER',id));
      bindCompareButtons(app);
    }catch(e){app.innerHTML=emptyProducts(e.message);}
  }

  function openReportComposer(targetType,targetId){
    if(!requireLogin('Log in to report content.'))return;
    openActionModal(`<span class="eyebrow">TRUST & SAFETY</span><h2 id="actionModalTitle">Report this ${esc(targetType.toLowerCase())}.</h2><p>Reports go to SANDMAN moderators. Do not submit false reports.</p><form id="reportForm" class="market-form"><label>Reason<select name="reason">${['SCAM','COUNTERFEIT','SEXUAL_CONTENT','HATE_ABUSE','IMPERSONATION','SPAM','DANGEROUS_PRODUCT','MISLEADING_LISTING','STOLEN_IMAGE','OTHER'].map(v=>`<option value="${v}">${titleCase(v)}</option>`).join('')}</select></label><label>Details<textarea name="details" maxlength="2000" rows="4"></textarea></label><button class="primary-btn wide">Send report</button></form>`);
    $('#reportForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{await api('/social/reports',{method:'POST',body:JSON.stringify({reason:f.get('reason'),details:f.get('details')||undefined,targetType,targetId})});closeActionModal();toast('Report sent to Trust & Safety');}catch(error){toast(error.message,'error');}};
  }

  async function renderPublicProfile(username){
    try{
      const data=await api(`/social/profiles/${encodeURIComponent(username)}`);
      const name=data.displayName||[data.firstName,data.lastName].filter(Boolean).join(' ')||`@${data.username}`;
      setPageMeta(`${name} — SANDMAN`,data.bio||'SANDMAN member profile.',`/profile/${encodeURIComponent(data.username)}`);
      app.innerHTML=`<div class="social-profile-page"><section class="social-profile-hero">${data.bannerUrl?`<img class="profile-banner" src="${esc(data.bannerUrl)}" alt="">`:''}<div class="social-profile-content">${data.avatarUrl?`<img class="social-avatar" src="${esc(data.avatarUrl)}" alt="">`:'<div class="social-avatar fallback">SM</div>'}<span class="eyebrow">SANDMAN PROFILE</span><h1>${esc(name)}${data.sellerProfile?.dealerVerifiedAt?' <span class="verified-inline" title="Verified Dealer">✓</span>':''}</h1>${data.sellerProfile?.dealerVerifiedAt?'<span class="verified-dealer-pill">✓ Verified Dealer</span>':''}<span class="profile-handle">@${esc(data.username)}</span><p>${esc(data.bio||'SANDMAN member.')}</p><div class="social-counts"><span><strong>${data._count.followers}</strong> followers</span><span><strong>${data._count.following}</strong> following</span><span><strong>${data._count.marketplaceProducts}</strong> listings</span></div><div class="profile-action-row">${data.isOwner?'<a class="secondary-btn" href="/account?tab=profile">Edit profile</a>':`<button class="${data.isFollowing?'secondary-btn':'primary-btn'}" id="profileFollow">${data.isFollowing?'Following ✓':'Follow'}</button>${state.token?'<button class="ghost-btn" id="profileBlock">Block</button><button class="ghost-btn" id="profileReport">Report</button>':''}`}</div></div></section><section class="section"><div class="section-inner social-profile-grid"><div><div class="section-head"><h2>Posts.</h2></div>${data.posts.length?`<div class="social-post-list">${data.posts.map(post=>socialPostCard(post,{...data,id:data.id})).join('')}</div>`:emptyProducts('No posts yet.')}</div><div><div class="section-head"><h2>Listings.</h2></div>${data.listings.length?`<div class="profile-listing-grid">${data.listings.map(item=>`<a class="profile-listing-card" href="/products/${encodeURIComponent(item.slug)}">${item.images?.[0]?.url?`<img src="${esc(item.images[0].url)}" alt="">`:''}<strong>${esc(item.name)}</strong><span>${money(item.priceCents,item.currency)}</span></a>`).join('')}</div>`:emptyProducts('No live listings.')}</div></div></section></div>`;
      $('#profileFollow')?.addEventListener('click',async()=>{try{if(data.isFollowing)await api(`/social/profiles/${data.id}/follow`,{method:'DELETE'});else await api(`/social/profiles/${data.id}/follow`,{method:'POST'});toast(data.isFollowing?'Unfollowed':'Following — activity alerts are on');renderPublicProfile(username);}catch(error){toast(error.message,'error');}});
      $('#profileBlock')?.addEventListener('click',async()=>{if(!confirm(`Block @${data.username}?`))return;try{await api(`/social/blocks/${data.id}`,{method:'POST'});toast('User blocked');navigate('/feed');}catch(error){toast(error.message,'error');}});
      $('#profileReport')?.addEventListener('click',()=>openReportComposer('USER',data.id));
    }catch(error){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">PROFILE</span><h1>Profile unavailable.</h1><p>${esc(error.message)}</p></div></section></div>`;}
  }

  function socialPostCard(post,user=post.user){
    const name=user?.displayName||user?.username||user?.firstName||'SANDMAN member';
    const media=Array.isArray(post.mediaUrls)?post.mediaUrls:[];
    return `<article class="social-post-card" data-post-id="${esc(post.id)}"><header>${user?.avatarUrl?`<img src="${esc(user.avatarUrl)}" alt="">`:'<span class="mini-avatar">SM</span>'}<div><strong>${esc(name)}</strong>${user?.username?`<a href="/profile/${encodeURIComponent(user.username)}">@${esc(user.username)}</a>`:''}<small>${new Date(post.createdAt).toLocaleString()}</small></div></header><p>${esc(post.body)}</p>${media.length?`<div class="post-media-grid">${media.map(url=>`<img src="${esc(url)}" alt="Post image" loading="lazy">`).join('')}</div>`:''}</article>`;
  }

  async function renderFeed(){
    if(!state.token)return renderAccountRequired('Your feed','Log in to follow sellers and see their newest posts and listings.');
    const feed=await api('/social/feed').catch(()=>({posts:[],listings:[]}));
    app.innerHTML=`<div class="dashboard-page social-feed-page"><div class="dashboard-head"><div><span class="eyebrow">FOLLOWING / FEED</span><h1>From people you follow.</h1><p>New posts and marketplace listings appear here and in your notification bell.</p></div><button class="primary-btn" id="newSocialPost">Create post</button></div><div class="feed-columns"><section><span class="eyebrow">POSTS</span><div class="social-post-list">${feed.posts.length?feed.posts.map(post=>socialPostCard(post)).join(''):emptyProducts('Follow a seller or create the first post in your network.')}</div></section><section><span class="eyebrow">NEW LISTINGS</span>${feed.listings.length?`<div class="feed-listing-list">${feed.listings.map(item=>`<a href="/products/${encodeURIComponent(item.slug)}"><strong>${esc(item.name)}</strong><span>${money(item.priceCents,item.currency)}</span><small>${esc(item.seller?.displayName||item.seller?.username||item.seller?.firstName||'Seller')}</small></a>`).join('')}</div>`:emptyProducts('No new followed listings.')}</section></div></div>`;
    $('#newSocialPost').onclick=()=>openSocialPostComposer();
  }

  function openSocialPostComposer(){
    if(!requireLogin())return;
    openActionModal(`<span class="eyebrow">CREATE POST</span><h2 id="actionModalTitle">Share with your followers.</h2><p>Posts and images are subject to SANDMAN content-safety rules.</p><form id="socialPostForm" class="market-form"><label>Post<textarea name="body" rows="6" minlength="1" maxlength="3000" required></textarea></label><label class="upload-drop">Photos<input id="socialPostPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><span class="upload-drop-icon">＋</span><strong>Add up to 6 photos</strong></label><button class="primary-btn wide">Publish post</button></form>`);
    $('#socialPostForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);const button=event.currentTarget.querySelector('button');button.disabled=true;try{const files=[...$('#socialPostPhotos').files].slice(0,6);const uploads=files.length?await uploadProductImages(files,'posts'):[];await api('/social/posts',{method:'POST',body:JSON.stringify({body:f.get('body'),mediaUrls:uploads.map(x=>x.url)})});closeActionModal();toast('Post published — followers will be notified');renderFeed();}catch(error){toast(error.message,'error');button.disabled=false;}};
  }


  async function renderSell(params = new URLSearchParams()) {
    if (!state.token) return renderAccountRequired('Sell a part', 'Create an account to list marketplace parts.');
    await loadGarage();
    const editId = params.get('edit');
    let config;
    let existing = null;
    try {
      [config, existing] = await Promise.all([
        api('/marketplace/seller-config'),
        editId ? api(`/marketplace/mine/${encodeURIComponent(editId)}`) : Promise.resolve(null),
      ]);
    } catch (error) { app.innerHTML = emptyProducts(error.message); return; }

    const images = (existing?.images || []).map((image, index) => ({ url:image.url, alt:image.alt || existing.name, position:index }));
    const selectedFitments = new Map((existing?.fitments || []).map(fitment => [fitment.vehicleVariantId, fitment.vehicleVariant || null]));
    const canPublish = Boolean(config.payoutsEnabled);
    const isEditing = Boolean(existing);
    const initialFitmentMode = existing?.isUniversal ? 'universal' : 'specific';
    const payoutNotice = canPublish ? '' : `<div class="seller-callout warning"><div><span class="eyebrow">PAYOUT VERIFICATION</span><strong>You can build your listing now.</strong><p>Save it as a draft with photos and details. Complete payout verification before making it public.</p></div><a class="secondary-btn" href="/seller?tab=payouts">Set up payouts</a></div>`;
    const vehicleLabel = variant => variant ? `${variant.yearStart}${variant.yearEnd !== variant.yearStart ? `–${variant.yearEnd}` : ''} ${variant.model?.make?.name || ''} ${variant.model?.name || ''}${variant.trim ? ` ${variant.trim}` : ''} · ${variant.engineCode || variant.engineName || 'Engine not listed'}`.replace(/\s+/g,' ').trim() : 'Saved vehicle fitment';

    app.innerHTML = `<div class="form-page seller-listing-page"><div class="form-layout"><div class="form-intro"><span class="eyebrow">MARKETPLACE / ${isEditing ? 'EDIT' : 'LIST'}</span><h1>${isEditing ? 'Edit your listing.' : 'Sell a part.'}</h1><p>Add accurate details and clear photos. SANDMAN takes ${config.commissionPercent}% commission after a successful sale.</p><div class="listing-tips"><span>01 · Use your own photos</span><span>02 · Show part number / condition</span><span>03 · Only claim fitment you know</span></div></div><div>${payoutNotice}<form class="market-form" id="sellForm"><div class="field-row"><label>Part name<input name="name" required maxlength="240" value="${esc(existing?.name || '')}"></label><label>Brand<input name="brand" maxlength="120" value="${esc(existing?.brand || '')}"></label></div><div class="field-row"><label>Category<select name="categoryId" required>${state.categories.map(c => `<option value="${c.id}" ${existing?.categoryId === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></label><label>Condition<select name="condition">${['USED','NEW','REMANUFACTURED','OPEN_BOX'].map(value => `<option ${existing?.condition === value ? 'selected' : ''}>${value}</option>`).join('')}</select></label></div><div class="field-row"><label>Price USD<input name="price" type="number" step="0.01" min="1" required value="${existing ? (existing.priceCents / 100).toFixed(2) : ''}"></label><label>Quantity<input name="stockQuantity" type="number" min="1" max="1000" value="${existing?.stockQuantity ?? 1}"></label></div><div class="field-row"><label>Shipping USD<input name="shipping" type="number" step="0.01" min="0" max="5000" value="${existing ? (existing.sellerShippingCents / 100).toFixed(2) : '0'}"></label><label>Location<input name="sellerLocation" maxlength="160" value="${esc(existing?.sellerLocation || '')}" placeholder="Johannesburg, South Africa"></label></div>
      <div class="listing-media-block"><div class="listing-media-head"><div><span class="eyebrow">PRODUCT PHOTOS</span><h2>Add up to 8 pictures</h2></div><span class="upload-count" id="listingImageCount">${images.length}/8</span></div><label class="upload-drop"><input id="listingImageFiles" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><span class="upload-drop-icon">＋</span><strong>Choose photos</strong><small>JPG, PNG or WebP · up to 10 MB each</small></label><div class="upload-url-row"><input id="listingImageUrl" type="url" placeholder="Or paste a direct HTTPS image URL"><button class="secondary-btn" id="addListingImageUrl" type="button">Add URL</button></div><div class="upload-grid" data-image-list></div><p class="form-note">The first image is the cover. Use clear, original photos. Direct URLs must point to the image itself, not an image-search page.</p></div>
      <label>Description<textarea name="description" rows="7" minlength="20" maxlength="8000" required>${esc(existing?.description || '')}</textarea></label><div class="field-row"><label>Manufacturer part number<input name="manufacturerPn" maxlength="120" value="${esc(existing?.manufacturerPn || '')}"></label><label>Warranty<input name="warrantyText" maxlength="1000" value="${esc(existing?.warrantyText || '')}"></label></div><div class="field-row"><label>Return days<input name="returnDays" type="number" min="0" max="365" value="${existing?.returnDays ?? ''}"></label><label>Video URL<input name="videoUrl" type="url" value="${esc(existing?.videoUrl || '')}"></label></div>
      <section class="listing-fitment-block"><div class="listing-media-head"><div><span class="eyebrow">FITMENT</span><h2>What does this part fit?</h2></div></div><div class="fitment-mode-grid"><label class="fitment-mode-card"><input type="radio" name="fitmentMode" value="specific" ${initialFitmentMode === 'specific' ? 'checked' : ''}><span><strong>Vehicle-specific</strong><small>Choose every vehicle variant you know this part fits.</small></span></label><label class="fitment-mode-card"><input type="radio" name="fitmentMode" value="universal" ${initialFitmentMode === 'universal' ? 'checked' : ''}><span><strong>Universal part</strong><small>No vehicle fitment is required.</small></span></label></div><div id="vehicleFitmentPanel"><label>Search the SANDMAN vehicle database<div class="fitment-search-wrap"><input id="fitmentVehicleSearch" type="search" autocomplete="off" placeholder="BMW M140i 2018 B58"><div class="fitment-search-results" id="fitmentSearchResults" hidden></div></div></label>${state.garage.length ? `<div class="garage-fitment-shortcuts"><span class="eyebrow">QUICK ADD FROM MY GARAGE</span>${state.garage.map((garageVehicle, index) => `<button type="button" class="fitment-quick-add" data-garage-fitment="${index}">＋ ${esc(vehicleName(garageVehicle))}</button>`).join('')}</div>` : ''}<div class="selected-fitments"><div class="selected-fitments-head"><strong>Selected compatible vehicles</strong><span id="selectedFitmentCount">0</span></div><div id="selectedFitmentList"></div></div><p class="form-note">You can save an unfinished draft. Before publishing a vehicle-specific part, at least one compatible SANDMAN vehicle variant is required.</p></div></section>
      <label class="commission-consent"><input name="commissionAccepted" type="checkbox" required ${isEditing ? 'checked' : ''}><span>I agree to the ${config.commissionPercent}% SANDMAN marketplace commission and seller rules.</span></label><div class="seller-form-actions"><button class="secondary-btn" type="submit" name="intent" value="draft">Save draft</button><button class="primary-btn" type="submit" name="intent" value="publish" ${canPublish ? '' : 'disabled title="Complete payout verification first"'}>${isEditing && existing.status === 'ACTIVE' ? 'Update live listing' : 'Publish listing'}</button></div></form></div></div></div>`;

    const form = $('#sellForm');
    const imageCount = () => { $('#listingImageCount').textContent = `${images.length}/8`; renderImageManager(form, images); };
    imageCount();
    $('#listingImageFiles').onchange = async event => {
      const files = [...event.target.files];
      if (!files.length) return;
      if (images.length + files.length > 8) { toast('A listing can have up to 8 photos.', 'error'); event.target.value = ''; return; }
      const drop = event.target.closest('.upload-drop');
      drop.classList.add('uploading');
      try {
        const uploaded = await uploadProductImages(files, 'marketplace');
        uploaded.forEach(image => { image.position = images.length; images.push(image); });
        imageCount(); toast(`${uploaded.length} photo${uploaded.length === 1 ? '' : 's'} uploaded`);
      } catch (error) { toast(error.message, 'error'); }
      finally { drop.classList.remove('uploading'); event.target.value = ''; }
    };
    $('#addListingImageUrl').onclick = () => {
      const input = $('#listingImageUrl'); const url = input.value.trim();
      if (!url) return;
      if (images.length >= 8) return toast('A listing can have up to 8 photos.', 'error');
      try {
        const parsed = new URL(url);
        if (parsed.protocol !== 'https:') throw new Error('https required');
        if (/\/(images\/search|search\/images)/i.test(parsed.pathname) || /(^|\.)bing\.com$/i.test(parsed.hostname)) throw new Error('search page');
      } catch { return toast('Use a direct HTTPS image URL, not an image-search page.', 'error'); }
      images.push({ url, alt:form.elements.name.value || 'Marketplace part', position:images.length }); input.value = ''; imageCount();
    };

    const fitmentPanel = $('#vehicleFitmentPanel');
    const fitmentSearch = $('#fitmentVehicleSearch');
    const fitmentResultsRoot = $('#fitmentSearchResults');
    let fitmentSearchTimer = null;
    let fitmentSearchResults = [];
    const selectedList = $('#selectedFitmentList');
    const selectedCount = $('#selectedFitmentCount');
    const currentFitmentMode = () => form.querySelector('input[name="fitmentMode"]:checked')?.value || 'specific';
    const renderSelectedFitments = () => {
      selectedCount.textContent = String(selectedFitments.size);
      selectedList.innerHTML = selectedFitments.size
        ? [...selectedFitments.entries()].map(([id, variant]) => `<div class="selected-fitment-row" data-selected-fitment="${esc(id)}"><span><strong>${esc(vehicleLabel(variant))}</strong>${variant?.chassisCode ? `<small>${esc(variant.chassisCode)}</small>` : ''}</span><button type="button" class="text-link danger-text" data-remove-fitment>Remove</button></div>`).join('')
        : '<div class="fitment-empty">No compatible vehicles selected yet.</div>';
      $$('[data-remove-fitment]', selectedList).forEach(button => button.onclick = () => {
        selectedFitments.delete(button.closest('[data-selected-fitment]').dataset.selectedFitment);
        renderSelectedFitments();
      });
    };
    const syncFitmentMode = () => {
      fitmentPanel.hidden = currentFitmentMode() === 'universal';
      if (fitmentPanel.hidden) { fitmentResultsRoot.hidden = true; fitmentSearch.value = ''; }
    };
    $$('input[name="fitmentMode"]', form).forEach(input => input.onchange = syncFitmentMode);
    renderSelectedFitments(); syncFitmentMode();

    $$('.fitment-quick-add', form).forEach(button => button.onclick = () => {
      const garageVehicle = state.garage[Number(button.dataset.garageFitment)];
      if (!garageVehicle?.vehicleVariantId || !garageVehicle.vehicleVariant) return;
      selectedFitments.set(garageVehicle.vehicleVariantId, garageVehicle.vehicleVariant);
      renderSelectedFitments();
    });

    const renderFitmentResults = () => {
      const available = fitmentSearchResults.filter(variant => !selectedFitments.has(variant.id));
      fitmentResultsRoot.innerHTML = available.length
        ? available.map((variant, index) => `<button type="button" class="fitment-result" data-fitment-result="${index}"><strong>${esc(vehicleLabel(variant))}</strong><small>${esc([variant.chassisCode, variant.engineName].filter(Boolean).join(' · '))}</small></button>`).join('')
        : '<div class="fitment-result-empty">No additional matching variants.</div>';
      fitmentResultsRoot.hidden = false;
      $$('[data-fitment-result]', fitmentResultsRoot).forEach(button => button.onclick = () => {
        const variant = available[Number(button.dataset.fitmentResult)];
        if (!variant) return;
        selectedFitments.set(variant.id, variant);
        renderSelectedFitments();
        fitmentSearchResults = fitmentSearchResults.filter(item => item.id !== variant.id);
        renderFitmentResults();
      });
    };
    fitmentSearch.oninput = () => {
      clearTimeout(fitmentSearchTimer);
      const q = fitmentSearch.value.trim();
      if (q.length < 2) { fitmentResultsRoot.hidden = true; fitmentResultsRoot.innerHTML = ''; return; }
      fitmentSearchTimer = setTimeout(async () => {
        try {
          fitmentResultsRoot.hidden = false;
          fitmentResultsRoot.innerHTML = '<div class="fitment-result-empty">Searching vehicle catalogue…</div>';
          fitmentSearchResults = await api(`/vehicles/search?q=${encodeURIComponent(q)}`);
          renderFitmentResults();
        } catch (error) {
          fitmentResultsRoot.innerHTML = `<div class="fitment-result-empty">${esc(error.message)}</div>`;
        }
      }, 250);
    };
    fitmentSearch.onkeydown = event => { if (event.key === 'Escape') fitmentResultsRoot.hidden = true; };

    form.onsubmit = async event => {
      event.preventDefault();
      const f = new FormData(form);
      const intent = event.submitter?.value === 'publish' ? 'publish' : 'draft';
      const vehicleSpecific = currentFitmentMode() === 'specific';
      const fitments = vehicleSpecific ? [...selectedFitments.keys()] : [];
      if (intent === 'publish' && vehicleSpecific && fitments.length === 0) return toast('Add at least one compatible vehicle before publishing, or mark the part Universal.', 'error');
      const payload = {
        name:f.get('name'), brand:f.get('brand') || undefined, manufacturerPn:f.get('manufacturerPn') || undefined,
        description:f.get('description'), categoryId:f.get('categoryId'), priceCents:Math.round(Number(f.get('price')) * 100), condition:f.get('condition'),
        stockQuantity:Number(f.get('stockQuantity')), sellerShippingCents:Math.round(Number(f.get('shipping')) * 100), sellerLocation:f.get('sellerLocation') || undefined,
        warrantyText:f.get('warrantyText') || undefined, returnDays:f.get('returnDays') ? Number(f.get('returnDays')) : undefined,
        videoUrl:f.get('videoUrl') || undefined, requiresFitment:vehicleSpecific, isUniversal:!vehicleSpecific,
        fitmentVehicleVariantIds:fitments, images:images.map((image, index) => ({ url:image.url, alt:image.alt || String(f.get('name')), position:index })),
      };
      const submitter = event.submitter;
      if (submitter) submitter.disabled = true;
      try {
        if (isEditing) {
          await api(`/marketplace/${encodeURIComponent(existing.id)}`, { method:'PATCH', body:JSON.stringify({ ...payload, status:intent === 'publish' ? 'ACTIVE' : 'DRAFT' }) });
          toast(intent === 'publish' ? 'Listing updated and live' : 'Draft saved');
        } else {
          const result = await api('/marketplace', { method:'POST', body:JSON.stringify({ ...payload, commissionAccepted:true, publish:intent === 'publish' }) });
          toast(result.publicationBlocked ? 'Listing saved as draft — finish payout setup to publish.' : intent === 'publish' ? 'Listing published' : 'Draft saved');
        }
        navigate('/seller?tab=listings');
      } catch (error) {
        toast(error.message, 'error');
        if (submitter) submitter.disabled = false;
      }
    };
  }

  async function renderSeller(params) {
    if (!state.token) return renderAccountRequired('Seller dashboard', 'Log in to manage your marketplace business.');
    const tab = params.get('tab') || 'overview';
    const [stats, listings, sales, offers, config] = await Promise.all([
      api('/community/seller/stats').catch(() => null), api('/marketplace/mine').catch(() => []), api('/marketplace/sales').catch(() => []), api('/community/offers').catch(() => []), api('/marketplace/seller-config').catch(() => null),
    ]);
    const nav = [['overview','Overview'],['listings','Listings'],['sales','Sales'],['offers','Offers'],['messages','Messages'],['cases','Cases'],['profile','Seller profile'],['payouts','Payouts']];
    const activeListings = listings.filter(item => item.status === 'ACTIVE');
    const drafts = listings.filter(item => item.status === 'DRAFT');
    const shippedSales = sales.filter(item => item.sellerShippedAt);
    const pendingShip = sales.filter(item => !item.sellerShippedAt);
    app.innerHTML = `<div class="dashboard-page seller-dashboard"><div class="dashboard-head seller-dashboard-head"><div><span class="eyebrow">SELLER / SANDMAN</span><h1>Seller studio.</h1><p>Manage listings, photos, sales, shipping, offers and your public seller profile.</p></div><div class="dashboard-head-actions"><a class="secondary-btn" href="#/account">My account</a><a class="primary-btn" href="#/sell">＋ List a part</a></div></div>${!config?.payoutsEnabled ? `<div class="seller-callout warning dashboard-callout"><div><span class="eyebrow">ACTION NEEDED</span><strong>Finish payout verification to publish listings.</strong><p>You can still create listings, upload photos and save drafts now.</p></div><a class="secondary-btn" href="#/seller?tab=payouts">Payout setup</a></div>` : ''}<div class="dashboard-grid"><nav class="dashboard-nav">${nav.map(([id,label]) => `<a class="${tab === id ? 'active' : ''}" href="#/seller?tab=${id}">${label}${id === 'listings' && drafts.length ? `<span class="nav-mini-count">${drafts.length}</span>` : ''}${id === 'sales' && pendingShip.length ? `<span class="nav-mini-count alert">${pendingShip.length}</span>` : ''}</a>`).join('')}</nav><div class="dashboard-content" id="sellerContent"></div></div></div>`;
    const root = $('#sellerContent');

    if (tab === 'overview') {
      const gross = stats?.grossCents || 0;
      root.innerHTML = `<section class="seller-welcome"><div><span class="eyebrow">THIS IS YOUR STORE</span><h2>${esc(state.user?.firstName || 'Seller')}, keep your garage moving.</h2><p>${activeListings.length} live listing${activeListings.length === 1 ? '' : 's'} · ${sales.length} sale${sales.length === 1 ? '' : 's'} · ${pendingShip.length} awaiting shipment</p></div><a class="text-link" href="#/seller-profile/${encodeURIComponent(state.user.id)}">View public profile ↗</a></section><div class="stat-cards seller-stat-cards"><div class="stat-card"><span>Gross sales</span><strong>${money(gross)}</strong><small>Paid marketplace items</small></div><div class="stat-card"><span>Live listings</span><strong>${activeListings.length}</strong><small>${drafts.length} draft${drafts.length === 1 ? '' : 's'}</small></div><div class="stat-card"><span>Views</span><strong>${stats?.views || 0}</strong><small>${stats?.wishlists || 0} wishlist saves</small></div><div class="stat-card"><span>Open offers</span><strong>${stats?.openOffers || 0}</strong><small>Respond quickly to buyers</small></div><div class="stat-card ${pendingShip.length ? 'attention' : ''}"><span>Shipping due</span><strong>${pendingShip.length}</strong><small>${shippedSales.length} already shipped</small></div><div class="stat-card"><span>Conversion</span><strong>${stats ? `${stats.conversionPercent.toFixed(1)}%` : '—'}</strong><small>Views to sold units</small></div></div><div class="seller-panel-grid"><section class="seller-panel"><div class="section-head"><div><span class="eyebrow">RECENT LISTINGS</span><h2>Your inventory</h2></div><a class="text-link" href="#/seller?tab=listings">Manage all</a></div>${listings.length ? `<div class="seller-mini-list">${listings.slice(0,4).map(item => `<a href="#/sell?edit=${encodeURIComponent(item.id)}"><span class="seller-mini-thumb">${imageOf(item) ? `<img src="${esc(imageOf(item))}" alt="">` : '◉'}</span><span><strong>${esc(item.name)}</strong><small>${titleCase(item.status)} · ${item.stockQuantity ?? 0} in stock</small></span><b>${money(item.priceCents)}</b></a>`).join('')}</div>` : emptyProducts('Create your first marketplace listing.')}</section><section class="seller-panel"><div class="section-head"><div><span class="eyebrow">RECENT SALES</span><h2>Orders to fulfil</h2></div><a class="text-link" href="#/seller?tab=sales">View sales</a></div>${sales.length ? `<div class="seller-mini-list">${sales.slice(0,4).map(item => `<a href="#/seller?tab=sales"><span class="seller-mini-thumb">${imageOf(item.product) ? `<img src="${esc(imageOf(item.product))}" alt="">` : '✓'}</span><span><strong>${esc(item.name)}</strong><small>${esc(item.order.orderNumber)} · ${item.sellerShippedAt ? 'Shipped' : 'Tracking needed'}</small></span><b>${money(item.totalPriceCents)}</b></a>`).join('')}</div>` : emptyProducts('Your paid marketplace sales will appear here.')}</section></div>`;
    } else if (tab === 'listings') {
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">YOUR MARKETPLACE INVENTORY</span><h2>${listings.length} listing${listings.length === 1 ? '' : 's'}</h2></div><a class="primary-btn" href="#/sell">New listing</a></div>${listings.length ? `<div class="seller-listing-list">${listings.map(item => `<article class="seller-listing-row" data-listing="${esc(item.id)}"><div class="seller-listing-image">${imageOf(item) ? `<img src="${esc(imageOf(item))}" alt="${esc(item.name)}">` : '<span>NO PHOTO</span>'}</div><div class="seller-listing-copy"><div class="listing-status-line"><span class="status ${item.status === 'ACTIVE' ? 'good' : ''}">${titleCase(item.status)}</span><small>${item.viewCount || 0} views · ${item.wishlistCount || 0} saves</small></div><h3>${esc(item.name)}</h3><p>${money(item.priceCents)} · ${item.stockQuantity ?? 0} in stock</p></div><div class="seller-listing-actions"><a class="secondary-btn" href="#/sell?edit=${encodeURIComponent(item.id)}">Edit</a>${item.status === 'ACTIVE' ? `<a class="ghost-btn" href="#/product/${encodeURIComponent(item.slug)}">View</a>` : config?.payoutsEnabled ? `<button class="ghost-btn" data-publish-listing>Publish</button>` : `<a class="ghost-btn" href="#/seller?tab=payouts">Payout setup</a>`}<button class="text-link danger-text" data-archive-listing>Archive</button></div></article>`).join('')}</div>` : emptyProducts('No listings yet.')}`;
      $$('[data-publish-listing]').forEach(button => button.onclick = async () => { const row = button.closest('[data-listing]'); try { await api(`/marketplace/${row.dataset.listing}`, { method:'PATCH', body:JSON.stringify({ status:'ACTIVE' }) }); toast('Listing published'); renderSeller(new URLSearchParams('tab=listings')); } catch (error) { toast(error.message, 'error'); } });
      $$('[data-archive-listing]').forEach(button => button.onclick = async () => { const row = button.closest('[data-listing]'); if (!confirm('Archive this listing? Buyers will no longer see it.')) return; try { await api(`/marketplace/${row.dataset.listing}`, { method:'DELETE' }); toast('Listing archived'); renderSeller(new URLSearchParams('tab=listings')); } catch (error) { toast(error.message, 'error'); } });
    } else if (tab === 'sales') {
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">PAID MARKETPLACE SALES</span><h2>Orders you've sold</h2></div><span class="subtle">${pendingShip.length} need tracking</span></div>${sales.length ? `<div class="seller-sales-list">${sales.map(item => { const destination = item.order.shippingAddress || {}; return `<article class="seller-sale-card" data-sale="${esc(item.id)}"><div class="seller-sale-top"><span class="seller-mini-thumb">${imageOf(item.product) ? `<img src="${esc(imageOf(item.product))}" alt="">` : '◉'}</span><div><span class="eyebrow">${esc(item.order.orderNumber)}</span><h3>${esc(item.name)}</h3><p>${item.quantity} × ${money(Math.round(item.totalPriceCents / Math.max(1,item.quantity)))} · ${fmtDate(item.order.createdAt)}</p></div><strong>${money(item.totalPriceCents)}</strong></div><div class="seller-sale-meta"><span>${item.sellerShippedAt ? `✓ Shipped ${esc(item.sellerCarrier || '')} · ${esc(item.sellerTrackingNumber || '')}` : 'Tracking not added yet'}</span><div class="seller-ship-to"><small>Ship to</small>${shippingAddressHtml(destination)}</div></div>${item.sellerShippedAt ? '' : `<form class="seller-shipping-form" data-ship-form><label>Carrier<input name="carrier" placeholder="DHL" required></label><label>Tracking number<input name="trackingNumber" required></label><button class="primary-btn" type="submit">Mark shipped</button></form>`}</article>`; }).join('')}</div>` : emptyProducts('No paid sales yet.')}`;
      $$('[data-ship-form]').forEach(form => form.onsubmit = async event => { event.preventDefault(); const card = form.closest('[data-sale]'); const data = new FormData(form); try { await api(`/marketplace/sales/${card.dataset.sale}/ship`, { method:'POST', body:JSON.stringify({ carrier:data.get('carrier'), trackingNumber:data.get('trackingNumber') }) }); toast('Tracking saved and buyer notified'); renderSeller(new URLSearchParams('tab=sales')); } catch (error) { toast(error.message, 'error'); } });
    } else if (tab === 'offers') {
      const mine = offers.filter(offer => offer.sellerId === state.user.id);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">NEGOTIATIONS</span><h2>Buyer offers</h2></div></div>${mine.length ? `<div class="data-list">${mine.map(offer => offerRow(offer, true)).join('')}</div>` : emptyProducts('No offers yet.')}`; bindOfferActions(root);
    } else if (tab === 'messages') {
      const conversations = await api('/community/conversations').catch(() => []);
      const mine = conversations.filter(conversation => conversation.sellerId === state.user.id);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">BUYER QUESTIONS</span><h2>Messages</h2></div><a class="secondary-btn" href="#/messages">Open inbox</a></div>${mine.length ? `<div class="seller-mini-list">${mine.slice(0,8).map(conversation => `<a href="#/messages?conversation=${encodeURIComponent(conversation.id)}"><span class="seller-mini-thumb">${imageOf(conversation.product) ? `<img src="${esc(imageOf(conversation.product))}" alt="">` : '◌'}</span><span><strong>${esc(conversation.product.name)}</strong><small>${esc(conversation.messages?.[0]?.body || 'Conversation')}</small></span><b>→</b></a>`).join('')}</div>` : emptyProducts('No buyer messages yet.')}`;
    } else if (tab === 'cases') {
      const cases = await api('/support/seller/cases').catch(() => []);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">BUYER PROTECTION</span><h2>Cases</h2></div></div>${cases.length ? `<div class="seller-cases">${cases.map(item => `<article class="seller-case-card" data-seller-case="${item.id}"><div><span class="status">${titleCase(item.status)}</span><h3>${titleCase(item.type)} · ${esc(item.order.orderNumber)}</h3><p>${esc(item.orderItem?.name || 'Order case')} · ${esc(item.reason)}</p>${item.sellerResponse ? `<blockquote>Your response: ${esc(item.sellerResponse)}</blockquote>` : ''}</div>${['RESOLVED','CLOSED','REJECTED'].includes(item.status) ? '' : `<form data-case-response><textarea name="response" rows="3" maxlength="2000" placeholder="Respond with useful details for the buyer and SANDMAN" required></textarea><button class="secondary-btn">Send response</button></form>`}</article>`).join('')}</div>` : emptyProducts('No buyer-protection cases.')}`;
      $$('[data-case-response]').forEach(form => form.onsubmit = async event => { event.preventDefault(); const row = form.closest('[data-seller-case]'); const data = new FormData(form); try { await api(`/support/seller/cases/${row.dataset.sellerCase}/respond`, { method:'POST', body:JSON.stringify({ response:data.get('response') }) }); toast('Response sent'); renderSeller(new URLSearchParams('tab=cases')); } catch (error) { toast(error.message, 'error'); } });
    } else if (tab === 'profile') {
      const me = await api(`/community/seller/${state.user.id}`).catch(() => ({ seller:{ sellerProfile:null } })); const profile = me.seller?.sellerProfile;
      root.innerHTML = `<div class="settings-section-head"><span class="eyebrow">PUBLIC SELLER PROFILE</span><h2>How buyers see you</h2><p>Build trust with a clear store name, location and realistic response expectations.</p></div><form id="sellerProfileForm" class="market-form settings-form"><div class="field-row"><label>Store name<input name="storeName" minlength="2" maxlength="100" value="${esc(profile?.storeName || '')}"></label><label>Location<input name="location" maxlength="160" value="${esc(profile?.location || '')}"></label></div><label>Response goal (hours)<input name="responseTimeHours" type="number" min="0" max="720" value="${profile?.responseTimeHours ?? ''}"></label><label>Bio<textarea name="bio" rows="6" maxlength="1000">${esc(profile?.bio || '')}</textarea></label><div class="seller-form-actions"><a class="secondary-btn" href="#/seller-profile/${encodeURIComponent(state.user.id)}">Preview profile</a><button class="primary-btn">Save profile</button></div></form>`;
      $('#sellerProfileForm').onsubmit = async event => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api('/community/seller/profile', { method:'PATCH', body:JSON.stringify({ storeName:data.get('storeName') || null, location:data.get('location') || null, bio:data.get('bio') || null, responseTimeHours:data.get('responseTimeHours') ? Number(data.get('responseTimeHours')) : null }) }); toast('Seller profile saved'); } catch (error) { toast(error.message, 'error'); } };
    } else if (tab === 'payouts') {
      const status = await api('/marketplace/payout/status').catch(() => ({ connected:false, payoutsEnabled:false, chargesEnabled:false }));
      const countryField = status.connected ? '' : `<label class="payout-country-field">Legal seller country <input id="sellerPayoutCountry" maxlength="2" pattern="[A-Za-z]{2}" autocomplete="country" value="${esc(config?.sellerCountry || '')}" placeholder="ZA"><small>Use the 2-letter country code for the person or business that will receive payouts. This cannot be casually changed after the payout account is created.</small></label>`;
      root.innerHTML = `<div class="payout-panel seller-payout-panel"><span class="eyebrow">SELLER PAYOUTS</span><h2>${status.payoutsEnabled ? 'Payout account ready.' : status.connected ? 'Finish payout verification.' : 'Connect a payout account.'}</h2><p>Your listings can be saved as drafts before payout verification. A verified payout destination is required before a listing can go live.</p><div class="payout-status-grid"><div><span>Account</span><strong>${status.connected ? 'Connected' : 'Not connected'}</strong></div><div><span>Payouts</span><strong>${status.payoutsEnabled ? 'Enabled' : 'Pending'}</strong></div><div><span>Funds flow</span><strong>Platform charge → seller transfer</strong></div></div>${countryField}<button class="primary-btn" id="payoutDashboard">${status.payoutsEnabled ? 'Open payout dashboard' : 'Start / continue setup'}</button></div>`;
      $('#payoutDashboard').onclick = async () => { try { if (status.payoutsEnabled) { const result = await api('/marketplace/payout/dashboard', { method:'POST' }); location.href = result.url; } else { const input = $('#sellerPayoutCountry'); const country = status.connected ? config?.sellerCountry : String(input?.value || '').trim().toUpperCase(); if (!status.connected && !/^[A-Z]{2}$/.test(country)) return toast('Enter a valid 2-letter seller country code.', 'error'); if (!country) return toast('Seller country is missing. Contact support before continuing payout setup.', 'error'); const result = await api('/marketplace/payout/onboard', { method:'POST', body:JSON.stringify({ country }) }); location.href = result.url; } } catch (error) { toast(error.message, 'error'); } };
    }
  }

  function offerRow(o,isSeller=false){const active=o.status==='OPEN',waiting=o.createdById===state.user.id;return `<div class="data-row offer-row" data-offer="${o.id}"><div><strong>${esc(o.product.name)}</strong><small>${titleCase(o.status)} · ${fmtDate(o.createdAt)} ${waiting?'· waiting for reply':''}</small></div><span>${money(o.amountCents)}</span><div class="row-buttons">${active&&!waiting?'<button data-offer-action="ACCEPT">Accept</button><button data-offer-action="COUNTER">Counter</button><button data-offer-action="DECLINE">Decline</button>':active&&waiting?'<button data-offer-action="CANCEL">Cancel</button>':''}${o.status==='ACCEPTED'&&o.buyerId===state.user.id?'<button data-buy-offer>Buy at offer</button>':''}</div></div>`;}
  function bindOfferActions(root){$$('[data-offer]',root).forEach(row=>{row.querySelectorAll('[data-offer-action]').forEach(btn=>btn.onclick=async()=>{const action=btn.dataset.offerAction;let amountCents;if(action==='COUNTER'){const val=prompt('Counter amount in USD:');if(!val)return;amountCents=Math.round(Number(val)*100);}try{await api(`/community/offers/${row.dataset.offer}/respond`,{method:'POST',body:JSON.stringify({action,amountCents})});toast('Offer updated');route();}catch(e){toast(e.message,'error');}});row.querySelector('[data-buy-offer]')?.addEventListener('click',async()=>{const offers=await api('/community/offers');const o=offers.find(x=>x.id===row.dataset.offer);if(o)await addToCart(o.productId,1,undefined,o.id);});});}

  function accountNav(tab) {
    const tabs = [['overview','Overview'],['purchases','Purchases'],['sales','Sales'],['listings','Listings'],['garage','Garage'],['wishlist','Wishlist'],['builds','Builds'],['messages','Messages'],['offers','Offers'],['cases','Buyer protection'],['profile','Profile & privacy'],['verification','Verification'],['notifications','Notifications'],['security','Security']];
    return `<nav class="dashboard-nav account-nav">${tabs.map(([id,label]) => `<a class="${tab === id ? 'active' : ''}" href="/account?tab=${id}">${label}</a>`).join('')}</nav>`;
  }

  async function renderAccount(params) {
    if (!state.token) return renderAccountRequired('Your account', 'Log in to view purchases, sales, garage, builds and settings.');
    const tab = params.get('tab') || 'overview';
    const verified = Boolean(state.user.emailVerified ?? state.user.emailVerifiedAt);
    const initials = `${state.user.firstName?.[0] || ''}${state.user.lastName?.[0] || ''}`.toUpperCase() || 'SM';
    app.innerHTML = `<div class="dashboard-page account-page"><div class="account-hero"><div class="account-avatar">${esc(initials)}</div><div class="account-identity"><span class="eyebrow">SANDMAN ACCOUNT</span><h1>${esc([state.user.firstName,state.user.lastName].filter(Boolean).join(' ') || 'Your account')}</h1><p>${esc(state.user.email)} · ${verified ? '<span class="verified-text">✓ Verified</span>' : '<span class="warning-text">Email not verified</span>'}</p></div><div class="account-hero-actions"><a class="secondary-btn" href="#/seller">Seller studio</a><button class="ghost-btn" id="accountSignOut">Sign out</button></div></div><div class="dashboard-grid">${accountNav(tab)}<div class="dashboard-content" id="accountContent"><div class="empty-state"><p>Loading…</p></div></div></div></div>`;
    $('#accountSignOut').onclick = logout;
    const root = $('#accountContent');

    if (tab === 'overview') {
      const [orders, sales, listings] = await Promise.all([api('/orders').catch(() => []), api('/marketplace/sales').catch(() => []), api('/marketplace/mine').catch(() => [])]);
      const spent = orders.filter(order => ['PAID','PARTIALLY_REFUNDED'].includes(order.paymentStatus)).reduce((sum, order) => sum + (order.totalCents || 0), 0);
      const sold = sales.reduce((sum, item) => sum + (item.totalPriceCents || 0), 0);
      root.innerHTML = `<section class="account-overview-intro"><div><span class="eyebrow">ONE ACCOUNT / BUY + SELL</span><h2>Everything around your cars and parts.</h2><p>Track what you've bought, what you've sold, your listings, Garage, Builds, messages and account security.</p></div><a class="primary-btn" href="#/shop">Shop parts</a></section><div class="account-stat-grid"><a href="#/account?tab=purchases"><span>Purchases</span><strong>${orders.length}</strong><small>${money(spent)} ordered</small></a><a href="#/account?tab=sales"><span>Sold items</span><strong>${sales.length}</strong><small>${money(sold)} gross sales</small></a><a href="#/account?tab=listings"><span>Listings</span><strong>${listings.length}</strong><small>${listings.filter(item => item.status === 'ACTIVE').length} live</small></a><a href="#/garage"><span>Garage</span><strong>${state.garage.length}</strong><small>Saved vehicles</small></a></div><div class="account-feature-grid"><a href="#/account?tab=purchases"><span class="account-feature-icon">▤</span><div><strong>Purchases</strong><small>Orders, payment status and tracking</small></div><b>→</b></a><a href="#/seller"><span class="account-feature-icon">◇</span><div><strong>Seller studio</strong><small>Listings, sales, offers and payouts</small></div><b>→</b></a><a href="#/garage"><span class="account-feature-icon">⌁</span><div><strong>My Garage</strong><small>Vehicles and exact fitment context</small></div><b>→</b></a><a href="#/builds"><span class="account-feature-icon">＋</span><div><strong>My Builds</strong><small>Parts, budgets and build targets</small></div><b>→</b></a><a href="#/messages"><span class="account-feature-icon">◌</span><div><strong>Messages</strong><small>Talk to marketplace buyers and sellers</small></div><b>→</b></a><a href="#/account?tab=profile"><span class="account-feature-icon">⚙</span><div><strong>Profile & settings</strong><small>Personal details, appearance and sign-in</small></div><b>→</b></a></div>`;
    } else if (tab === 'purchases') {
      const orders = await api('/orders').catch(() => []);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">PURCHASE HISTORY</span><h2>Things you've bought</h2></div><a class="secondary-btn" href="#/shop">Continue shopping</a></div>${orders.length ? `<div class="account-order-list">${orders.map(order => `<a class="account-order-card" href="#/order/${encodeURIComponent(order.orderNumber)}"><div><span class="eyebrow">${esc(order.orderNumber)}</span><h3>${order.items.length} item${order.items.length === 1 ? '' : 's'}</h3><p>${fmtDate(order.createdAt)} · ${titleCase(order.paymentStatus || order.status)}</p></div><div><strong>${money(order.totalCents)}</strong><span class="status">${titleCase(order.status)}</span></div></a>`).join('')}</div>` : emptyProducts('No purchases yet.')}`;
    } else if (tab === 'sales') {
      const sales = await api('/marketplace/sales').catch(() => []);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">MARKETPLACE SALES</span><h2>Things you've sold</h2></div><a class="secondary-btn" href="#/seller?tab=sales">Open seller studio</a></div>${sales.length ? `<div class="account-sale-list">${sales.map(item => `<article class="account-sale-card"><span class="seller-mini-thumb">${imageOf(item.product) ? `<img src="${esc(imageOf(item.product))}" alt="">` : '◉'}</span><div><strong>${esc(item.name)}</strong><small>${esc(item.order.orderNumber)} · ${fmtDate(item.order.createdAt)}</small></div><span>${money(item.totalPriceCents)}</span><span class="status">${item.sellerShippedAt ? 'Shipped' : 'Ship item'}</span><a class="row-action" href="#/seller?tab=sales">Manage</a></article>`).join('')}</div>` : emptyProducts('You have not sold anything yet.')}`;
    } else if (tab === 'listings') {
      const listings = await api('/marketplace/mine').catch(() => []);
      root.innerHTML = `<div class="section-head"><div><span class="eyebrow">YOUR LISTINGS</span><h2>Parts you're selling</h2></div><a class="primary-btn" href="#/sell">＋ List a part</a></div>${listings.length ? `<div class="account-listing-grid">${listings.map(item => `<a href="#/sell?edit=${encodeURIComponent(item.id)}"><div class="account-listing-image">${imageOf(item) ? `<img src="${esc(imageOf(item))}" alt="${esc(item.name)}">` : '<span>No photo</span>'}</div><span class="status">${titleCase(item.status)}</span><h3>${esc(item.name)}</h3><p>${money(item.priceCents)} · ${item.stockQuantity ?? 0} stock</p></a>`).join('')}</div>` : emptyProducts('No listings yet.')}`;
    } else if (tab === 'garage') {
      location.hash = '#/garage'; return;
    } else if (tab === 'wishlist') {
      location.hash = '#/wishlist'; return;
    } else if (tab === 'builds') {
      location.hash = '#/builds'; return;
    } else if (tab === 'messages') {
      location.hash = '#/messages'; return;
    } else if (tab === 'offers') {
      const offers = await api('/community/offers').catch(() => []); root.innerHTML = `<div class="section-head"><div><span class="eyebrow">BUY + SELL</span><h2>Offers</h2></div></div>${offers.length ? `<div class="data-list">${offers.map(offer => offerRow(offer, offer.sellerId === state.user.id)).join('')}</div>` : emptyProducts('No offers yet.')}`; bindOfferActions(root);
    } else if (tab === 'cases') {
      const cases = await api('/support/cases').catch(() => []); root.innerHTML = `<div class="section-head"><div><span class="eyebrow">BUYER PROTECTION</span><h2>Your cases</h2></div><a class="primary-btn" href="/returns-center">Open case</a></div>${cases.length ? `<div class="data-list">${cases.map(item => `<div class="data-row"><div><strong>${titleCase(item.type)}</strong><small>${esc(item.reason)} · Order ${esc(item.order.orderNumber)}</small></div><span class="status">${titleCase(item.status)}</span></div>`).join('')}</div>` : emptyProducts('No support cases.')}`;
    } else if (tab === 'profile') {
      const social = await api('/social/notification-preferences').catch(() => null);
      root.innerHTML = `<div class="settings-section-head"><span class="eyebrow">PROFILE & PRIVACY</span><h2>Your SANDMAN identity</h2><p>Choose a unique username, control what other members can see and keep your personal details accurate.</p></div>
      <div class="profile-settings-grid">
        <section class="profile-setting-card profile-main-card"><span class="eyebrow">PUBLIC PROFILE</span><form id="socialProfileForm" class="market-form settings-form">
          <div class="profile-media-row"><div class="profile-avatar-preview">${state.user.avatarUrl?`<img src="${esc(state.user.avatarUrl)}" alt="">`:`${esc(initials)}`}</div><div><label class="secondary-btn upload-inline">Change profile photo<input id="avatarUpload" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><small>Images are safety-scanned before publication.</small></div></div>
          <div class="field-row"><label>Username<input name="username" minlength="3" maxlength="30" value="${esc(state.user.username || '')}" placeholder="yourname"></label><label>Display name<input name="displayName" maxlength="80" value="${esc(state.user.displayName || '')}"></label></div>
          <div class="field-row"><label>First name<input name="firstName" maxlength="80" value="${esc(state.user.firstName || '')}"></label><label>Last name<input name="lastName" maxlength="80" value="${esc(state.user.lastName || '')}"></label></div>
          <label>Bio<textarea name="bio" maxlength="600" rows="4">${esc(state.user.bio || '')}</textarea></label><label>Country<input name="country" maxlength="80" value="${esc(state.user.country || '')}"></label>
          <button class="primary-btn">Save profile</button>${state.user.username?`<a class="secondary-btn" href="/profile/${encodeURIComponent(state.user.username)}">View public profile</a>`:''}
        </form></section>
        <section class="profile-setting-card"><span class="eyebrow">PRIVACY</span><h3>Who can see and contact you</h3><form id="privacyForm" class="market-form settings-form"><label>Profile visibility<select name="profileVisibility">${['PUBLIC','FOLLOWERS','PRIVATE'].map(v=>`<option value="${v}" ${state.user.profileVisibility===v?'selected':''}>${titleCase(v)}</option>`).join('')}</select></label><label>Garage visibility<select name="garageVisibility">${['PUBLIC','FOLLOWERS','PRIVATE'].map(v=>`<option value="${v}" ${state.user.garageVisibility===v?'selected':''}>${titleCase(v)}</option>`).join('')}</select></label><label>Messages<select name="messagePrivacy">${['EVERYONE','FOLLOWERS','NOBODY'].map(v=>`<option value="${v}" ${state.user.messagePrivacy===v?'selected':''}>${titleCase(v)}</option>`).join('')}</select></label><label class="check-line"><input name="showFollowing" type="checkbox" ${state.user.showFollowing!==false?'checked':''}> Show follower/following lists</label><label class="check-line"><input name="showOnlineStatus" type="checkbox" ${state.user.showOnlineStatus?'checked':''}> Show online status</label><button class="secondary-btn">Save privacy</button></form></section>
        <section class="profile-setting-card"><span class="eyebrow">PHONE</span><h3>${state.user.phoneVerified?'Phone verified ✓':'Verify your phone'}</h3><form id="phoneForm" class="market-form settings-form"><label>Mobile number<input name="phone" type="tel" value="${esc(state.user.phone || '')}" placeholder="+27821234567"></label><button class="secondary-btn" type="submit">${state.user.phoneVerified?'Update phone':'Save & send code'}</button></form><div id="phoneVerifyArea">${state.user.phone&&!state.user.phoneVerified?'<button class="text-link" id="sendPhoneCode">Send verification text</button>':''}</div></section>
        <section class="profile-setting-card"><span class="eyebrow">SIGN-IN EMAIL</span><h3>${esc(state.user.email)}</h3><p>Changing your sign-in email requires your password${state.user.twoFactorEnabled?' and 2FA':''}, then confirmation from the new inbox.</p><button class="secondary-btn" id="changeEmailButton">Change email</button></section>
        <section class="profile-setting-card"><span class="eyebrow">APPEARANCE</span><h3>Theme</h3><p>Light and dark mode now use the same design tokens across forms, cards and overlays.</p><div class="theme-choice-grid"><button type="button" data-account-theme="light" class="${currentTheme()==='light'?'active':''}"><span>☼</span><strong>Light</strong></button><button type="button" data-account-theme="dark" class="${currentTheme()==='dark'?'active':''}"><span>☾</span><strong>Dark</strong></button></div></section>
        <section class="profile-setting-card"><span class="eyebrow">NOTIFICATIONS</span><h3>Activity alerts</h3><p>Choose whether followed-account activity and marketplace updates also reach your email.</p><a class="secondary-btn" href="/account?tab=notifications">Notification preferences</a></section>
        <section class="profile-setting-card"><span class="eyebrow">YOUR DATA</span><h3>Export your SANDMAN data</h3><p>Download a JSON copy of your profile, purchases, garage, builds, posts, listings, reviews and account activity.</p><button class="secondary-btn" id="exportAccountData">Download my data</button></section>
        <section class="profile-setting-card danger-card"><span class="eyebrow">ACCOUNT CONTROL</span><h3>Deactivate & request deletion</h3><p>This signs you out everywhere, removes your public profile/posts and archives active marketplace listings. Transaction records may still be retained where required.</p><button class="secondary-btn danger-text" id="deactivateAccount">Deactivate account</button><button class="text-link" id="profileSignOut">Just sign out</button></section>
      </div>`;
      let avatarUrl = state.user.avatarUrl || null;
      $('#avatarUpload')?.addEventListener('change', async event => { const file=event.target.files?.[0]; if(!file)return; try{const [upload]=await uploadProductImages([file],'profile'); avatarUrl=upload.url; const updated=await api('/social/profile',{method:'PATCH',body:JSON.stringify({avatarUrl})}); state.user={...state.user,...updated}; toast('Profile photo updated'); renderAccount(new URLSearchParams('tab=profile'));}catch(error){toast(error.message,'error');} });
      $('#socialProfileForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{const updated=await api('/social/profile',{method:'PATCH',body:JSON.stringify({username:f.get('username')||undefined,displayName:f.get('displayName')||null,firstName:f.get('firstName')||null,lastName:f.get('lastName')||null,bio:f.get('bio')||null,country:f.get('country')||null,avatarUrl})});state.user={...state.user,...updated,emailVerified:verified,phoneVerified:Boolean(updated.phoneVerifiedAt||state.user.phoneVerified)};updateAccountUi();toast('Profile saved');renderAccount(new URLSearchParams('tab=profile'));}catch(error){toast(error.message,'error');}};
      $('#privacyForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{const updated=await api('/social/profile',{method:'PATCH',body:JSON.stringify({profileVisibility:f.get('profileVisibility'),garageVisibility:f.get('garageVisibility'),messagePrivacy:f.get('messagePrivacy'),showFollowing:f.get('showFollowing')==='on',showOnlineStatus:f.get('showOnlineStatus')==='on'})});state.user={...state.user,...updated};toast('Privacy settings saved');}catch(error){toast(error.message,'error');}};
      $('#phoneForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{state.user=await api('/auth/me',{method:'PATCH',body:JSON.stringify({phone:f.get('phone')||null})});updateAccountUi();if(state.user.phone&&!state.user.phoneVerified){await api('/auth/phone-verification/request',{method:'POST'});showPhoneCodeForm();toast('Verification text sent');}else toast('Phone updated');}catch(error){toast(error.message,'error');}};
      const showPhoneCodeForm=()=>{const area=$('#phoneVerifyArea');if(!area)return;area.innerHTML=`<form id="phoneCodeForm" class="verification-code-form"><label>6-digit text code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="primary-btn">Verify phone</button></form>`;$('#phoneCodeForm').onsubmit=async event=>{event.preventDefault();try{await api('/auth/phone-verification/confirm',{method:'POST',body:JSON.stringify({code:new FormData(event.currentTarget).get('code')})});await hydrateUser();toast('Phone verified');renderAccount(new URLSearchParams('tab=profile'));}catch(error){toast(error.message,'error');}};};
      $('#sendPhoneCode')?.addEventListener('click',async()=>{try{await api('/auth/phone-verification/request',{method:'POST'});showPhoneCodeForm();toast('Verification text sent');}catch(error){toast(error.message,'error');}});
      $('#changeEmailButton')?.addEventListener('click',()=>{
        openActionModal(`<span class="eyebrow">CHANGE SIGN-IN EMAIL</span><h2 id="actionModalTitle">Verify this sensitive change.</h2><p>SANDMAN will send a six-digit confirmation code and secure link to the new address.</p><form id="changeEmailForm" class="market-form"><label>New email<input name="newEmail" type="email" autocomplete="email" required></label><label>Current password<input name="password" type="password" autocomplete="current-password" required></label>${state.user.twoFactorEnabled?'<label>Authenticator / recovery code<input name="code" autocomplete="one-time-code" required></label>':''}<button class="primary-btn wide">Send confirmation</button></form>`);
        $('#changeEmailForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);try{await api('/auth/email-change/request',{method:'POST',body:JSON.stringify({newEmail:f.get('newEmail'),password:f.get('password'),code:f.get('code')||undefined})});$('#actionModalContent').innerHTML=`<span class="eyebrow">CHECK YOUR NEW INBOX</span><h2 id="actionModalTitle">Confirm the new email.</h2><p>Enter the six-digit code SANDMAN sent to ${esc(f.get('newEmail'))}.</p><form id="confirmEmailChangeForm" class="market-form"><label>6-digit code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus></label><button class="primary-btn wide">Confirm email change</button></form>`;$('#confirmEmailChangeForm').onsubmit=async e=>{e.preventDefault();try{const result=await api('/auth/email-change/confirm',{method:'POST',body:JSON.stringify({code:new FormData(e.currentTarget).get('code')})});setToken(result.token,result.user);await hydrateUser();closeActionModal();toast('Sign-in email changed');renderAccount(new URLSearchParams('tab=profile'));}catch(error){toast(error.message,'error');}};}catch(error){toast(error.message,'error');}};
      });
      const sensitiveAccountModal=(title,copy,submitLabel,onSubmit,confirmDelete=false)=>{openActionModal(`<span class="eyebrow">SECURITY CHECK</span><h2 id="actionModalTitle">${esc(title)}</h2><p>${esc(copy)}</p><form id="accountSensitiveForm" class="market-form"><label>Current password<input name="password" type="password" autocomplete="current-password" required></label>${state.user.twoFactorEnabled?'<label>Authenticator / recovery code<input name="code" autocomplete="one-time-code" required></label>':''}${confirmDelete?'<label>Type DELETE to confirm<input name="confirm" autocomplete="off" pattern="DELETE" required></label>':''}<button class="primary-btn wide">${esc(submitLabel)}</button></form>`);$('#accountSensitiveForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);await onSubmit({password:f.get('password'),code:f.get('code')||undefined,confirm:f.get('confirm')||undefined});};};
      $('#exportAccountData')?.addEventListener('click',()=>sensitiveAccountModal('Download your account data','For privacy, confirm your password and second factor before SANDMAN prepares the export.','Prepare download',async body=>{try{const data=await api('/auth/account/export',{method:'POST',body:JSON.stringify(body)});const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`sandman-account-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);closeActionModal();toast('Account data downloaded');}catch(error){toast(error.message,'error');}}));
      $('#deactivateAccount')?.addEventListener('click',()=>sensitiveAccountModal('Deactivate your SANDMAN account','This immediately signs out every device, removes your public identity and archives active marketplace listings. Type DELETE only if you want to continue.','Deactivate account',async body=>{try{await api('/auth/account/deactivate',{method:'POST',body:JSON.stringify(body)});setToken('',null);state.cart=null;state.garage=[];state.builds=[];state.notifications={items:[],unread:0};closeActionModal();navigate('/');toast('Account deactivated');}catch(error){toast(error.message,'error');}},true));
      $$('[data-account-theme]').forEach(button=>button.onclick=()=>{setTheme(button.dataset.accountTheme);renderAccount(new URLSearchParams('tab=profile'));});
      $('#profileSignOut').onclick=logout;
    } else if (tab === 'verification') {
      const verification=await api('/trust/dealer-verification').catch(()=>({requirements:{emailVerified:verified,phoneVerified:Boolean(state.user.phoneVerified),twoFactorEnabled:Boolean(state.user.twoFactorEnabled)},application:null,verifiedDealer:false}));
      const reqs=verification.requirements;
      root.innerHTML=`<div class="settings-section-head"><span class="eyebrow">IDENTITY & DEALER VERIFICATION</span><h2>Build trust before you sell at scale.</h2><p>Email, phone and 2FA protect the account. Dealer verification is reviewed by SANDMAN staff.</p></div><div class="verification-grid">
        <section class="profile-setting-card"><span class="eyebrow">EMAIL VERIFICATION</span><h3>${reqs.emailVerified?'Verified ✓':'Verify your email'}</h3><p>${reqs.emailVerified?'Your email address is confirmed.':'SANDMAN sends a six-digit code and secure link to your inbox.'}</p>${reqs.emailVerified?'':`<button class="secondary-btn" id="sendVerification">Send verification email</button><form id="emailCodeForm" class="verification-code-form"><label>6-digit email code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="primary-btn">Verify email</button></form>`}</section>
        <section class="profile-setting-card"><span class="eyebrow">PHONE VERIFICATION</span><h3>${reqs.phoneVerified?'Verified ✓':(state.user.phone?'Ready to verify':'Add a phone number first')}</h3><p>SMS verification confirms the phone linked to your account. It does not replace email verification.</p><a class="secondary-btn" href="/account?tab=profile">Manage phone</a></section>
        <section class="profile-setting-card"><span class="eyebrow">TWO-FACTOR</span><h3>${reqs.twoFactorEnabled?'Enabled ✓':'Required for dealers'}</h3><p>Authenticator-based 2FA protects sign-in and sensitive account changes.</p><a class="secondary-btn" href="/account?tab=security">Security settings</a></section>
        <section class="profile-setting-card dealer-card"><span class="eyebrow">VERIFIED DEALER</span><h3>${verification.verifiedDealer?'Verified Dealer ✓':verification.application?titleCase(verification.application.status):'Apply for verification'}</h3><p>Dealer status is only awarded after account-security checks and a manual business review.</p><div id="dealerApplicationArea"></div></section>
      </div>`;
      $('#sendVerification')?.addEventListener('click',async()=>{try{await api('/auth/email-verification/request',{method:'POST'});toast('Verification email sent');}catch(error){toast(error.message,'error');}});
      $('#emailCodeForm')?.addEventListener('submit',async event=>{event.preventDefault();try{await api('/auth/email-verification/confirm-code',{method:'POST',body:JSON.stringify({code:new FormData(event.currentTarget).get('code')})});await hydrateUser();toast('Email verified');renderAccount(new URLSearchParams('tab=verification'));}catch(error){toast(error.message,'error');}});
      const canApply=reqs.emailVerified&&reqs.phoneVerified&&reqs.twoFactorEnabled&&!verification.verifiedDealer&&verification.application?.status!=='PENDING';
      const dealerArea=$('#dealerApplicationArea');
      if(verification.application?.status==='PENDING') dealerArea.innerHTML='<p class="status-banner">Application submitted — awaiting Trust & Safety review.</p>';
      else if(canApply){dealerArea.innerHTML=`<form id="dealerForm" class="market-form settings-form"><label>Business name<input name="businessName" minlength="2" maxlength="160" required></label><div class="field-row"><label>Registration number<input name="registrationNumber" maxlength="120"></label><label>Country<input name="country" maxlength="80" required></label></div><label>Business email<input name="businessEmail" type="email" required value="${esc(state.user.email)}"></label><label>Website<input name="website" type="url" placeholder="https://"></label><label>Address<input name="address" maxlength="300"></label><label>Description<textarea name="description" maxlength="1500" rows="4"></textarea></label><label class="upload-drop">Verification documents<input id="dealerDocs" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><span class="upload-drop-icon">＋</span><strong>Add supporting documents</strong><small>Images are safety-scanned. Up to 8 files.</small></label><button class="primary-btn">Submit dealer application</button></form>`;$('#dealerForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{const uploads=$('#dealerDocs').files?.length?await uploadProductImages([...$('#dealerDocs').files].slice(0,8),'dealer'):[];await api('/trust/dealer-verification',{method:'POST',body:JSON.stringify({businessName:f.get('businessName'),registrationNumber:f.get('registrationNumber')||undefined,country:f.get('country'),address:f.get('address')||undefined,website:f.get('website')||undefined,businessEmail:f.get('businessEmail'),description:f.get('description')||undefined,documentUrls:uploads.map(x=>x.url)})});toast('Dealer application submitted');renderAccount(new URLSearchParams('tab=verification'));}catch(error){toast(error.message,'error');button.disabled=false;}};}
      else if(!verification.verifiedDealer&&!verification.application) dealerArea.innerHTML='<p class="warning-text">Complete email verification, phone verification and 2FA before applying.</p>';
    } else if (tab === 'notifications') {
      const pref=await api('/social/notification-preferences');
      root.innerHTML=`<div class="settings-section-head"><span class="eyebrow">NOTIFICATIONS</span><h2>Choose your alerts.</h2><p>Security alerts stay protected; other channels are under your control.</p></div><form id="notificationPrefsForm" class="notification-pref-grid">${[
        ['inAppFollowers','New followers','Website'],['inAppFollowingActivity','People I follow post or list','Website'],['inAppMessages','Messages','Website'],['inAppMarketplace','Marketplace activity','Website'],['inAppOrders','Order updates','Website'],['emailFollowingActivity','People I follow post or list','Email'],['emailMessages','Messages','Email'],['emailMarketplace','Marketplace activity','Email'],['emailOrders','Order updates','Email'],['emailSecurity','Security alerts','Email']
      ].map(([key,label,channel])=>`<label class="notification-pref-row"><span><strong>${label}</strong><small>${channel}</small></span><input type="checkbox" name="${key}" ${pref[key]?'checked':''}></label>`).join('')}<button class="primary-btn">Save notification preferences</button></form>`;
      $('#notificationPrefsForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);const body={};['inAppFollowers','inAppFollowingActivity','inAppMessages','inAppMarketplace','inAppOrders','emailFollowingActivity','emailMessages','emailMarketplace','emailOrders','emailSecurity'].forEach(key=>body[key]=f.get(key)==='on');try{await api('/social/notification-preferences',{method:'PATCH',body:JSON.stringify(body)});toast('Notification preferences saved');}catch(error){toast(error.message,'error');}};
    } else if (tab === 'security') {
      await renderSecurityPanel(root);
    }
  }

  async function renderSecurityPanel(root){
    const [sessions,status,events]=await Promise.all([api('/security/sessions'),api('/security/2fa/status'),api('/security/events').catch(()=>[])]);
    root.innerHTML=`<div class="settings-section-head"><span class="eyebrow">ACCOUNT SECURITY</span><h2>Protect your SANDMAN account.</h2><p>Use a strong password, authenticator-based two-factor authentication and session controls.</p></div>
      <div class="security-grid">
        <section class="account-security"><span class="eyebrow">PASSWORD</span><h3>Change password</h3><p>Use at least 10 characters with uppercase, lowercase and a number.</p><form id="accountPasswordForm" class="market-form settings-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input name="newPassword" type="password" minlength="10" autocomplete="new-password" required></label>${status.enabled?'<label>Authenticator / recovery code<input name="code" autocomplete="one-time-code" minlength="6" maxlength="32" required></label>':''}<button class="secondary-btn">Update password</button></form></section>
        <section class="account-security two-factor-card"><span class="eyebrow">TWO-FACTOR AUTHENTICATION</span><h3>${status.enabled?'2FA is on ✓':'Secure sign-in with an authenticator'}</h3><p>${status.enabled?`Enabled ${status.enabledAt?fmtDate(status.enabledAt):''}. ${status.recoveryCodesRemaining} recovery codes remaining.`:'Scan a QR code with Google Authenticator, Microsoft Authenticator, 1Password or another TOTP app.'}</p><div id="twoFactorArea">${status.enabled?`<div class="security-action-row"><button class="secondary-btn" id="regenerateRecovery">New recovery codes</button><button class="secondary-btn danger-text" id="disable2fa">Disable 2FA</button></div>`:'<button class="primary-btn" id="setup2fa">Set up 2FA</button>'}</div></section>
        <section class="account-security security-sessions"><span class="eyebrow">ACTIVE SESSIONS</span><h3>Your devices</h3><div class="data-list">${sessions.map(s=>`<div class="data-row" data-session="${s.id}"><div><strong>${s.current?'This device':'Signed-in device'}</strong><small>${esc(s.userAgent||'Unknown browser')}<br>${esc(s.ipAddress||'Unknown network')} · last used ${fmtDate(s.lastUsedAt)}</small></div>${s.current?'<span class="status">Current</span>':'<button class="text-link danger-text" data-revoke>Sign out</button>'}</div>`).join('')}</div><button class="secondary-btn" id="revokeOthers">Sign out other devices</button></section>
        <section class="account-security"><span class="eyebrow">RECENT SECURITY ACTIVITY</span><h3>Security events</h3><div class="data-list">${events.length?events.slice(0,10).map(event=>`<div class="data-row"><div><strong>${titleCase(event.type)}</strong><small>${new Date(event.createdAt).toLocaleString()}${event.ipAddress?` · ${esc(event.ipAddress)}`:''}</small></div></div>`).join(''):'<p class="form-note">No recent security events.</p>'}</div></section>
      </div><button class="secondary-btn" id="logoutButton">Log out</button>`;

    $('#accountPasswordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword'),code:f.get('code')||undefined})});setToken(r.token,r.user);toast('Password changed — other devices signed out');e.currentTarget.reset();await hydrateUser();}catch(err){toast(err.message,'error');}};

    $('#setup2fa')?.addEventListener('click',()=>{
      openActionModal(`<span class="eyebrow">TWO-FACTOR AUTHENTICATION</span><h2 id="actionModalTitle">Secure your account.</h2><p>Confirm your password before SANDMAN creates a temporary authenticator setup.</p><form id="start2faForm" class="market-form"><label>Current password<input name="password" type="password" autocomplete="current-password" required autofocus></label><button class="primary-btn wide">Continue</button></form>`);
      $('#start2faForm').onsubmit=async event=>{event.preventDefault();const password=new FormData(event.currentTarget).get('password');try{const setup=await api('/security/2fa/setup',{method:'POST',body:JSON.stringify({password})});$('#actionModalContent').innerHTML=`<span class="eyebrow">TWO-FACTOR AUTHENTICATION</span><h2 id="actionModalTitle">Scan the QR code.</h2><p>Use your authenticator app, then enter the six-digit code it generates. The setup secret stays pending until this code succeeds.</p><div class="two-factor-setup"><div class="qr-shell"><img src="${esc(setup.qrDataUrl)}" alt="SANDMAN authenticator QR code"></div><details class="manual-key"><summary>Can't scan the QR code?</summary><p>Enter this setup key manually. Keep it private.</p><div class="manual-key-row"><code id="manual2faKey">${esc(setup.manualKey)}</code><button type="button" class="text-link" id="copy2faKey">Copy</button></div></details><form id="enable2faForm" class="market-form"><label>6-digit authenticator code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="primary-btn wide">Verify & enable 2FA</button></form></div>`;$('#copy2faKey').onclick=async()=>{await navigator.clipboard?.writeText(setup.manualKey);toast('Setup key copied');};$('#enable2faForm').onsubmit=async e=>{e.preventDefault();try{const result=await api('/security/2fa/enable',{method:'POST',body:JSON.stringify({code:new FormData(e.currentTarget).get('code')})});$('#actionModalContent').innerHTML=`<span class="eyebrow">RECOVERY CODES</span><h2 id="actionModalTitle">Save these somewhere safe.</h2><p>Each recovery code works once if you lose access to your authenticator. SANDMAN will not show this set again.</p><div class="recovery-code-grid">${result.recoveryCodes.map(code=>`<code>${esc(code)}</code>`).join('')}</div><div class="security-action-row"><button class="secondary-btn" id="copyRecovery">Copy all</button><button class="primary-btn" id="finish2fa">I've saved them</button></div>`;$('#copyRecovery').onclick=async()=>{await navigator.clipboard?.writeText(result.recoveryCodes.join('\n'));toast('Recovery codes copied');};$('#finish2fa').onclick=()=>{closeActionModal();toast('2FA enabled');renderAccount(new URLSearchParams('tab=security'));};}catch(error){toast(error.message,'error');}};}catch(error){toast(error.message,'error');}};
    });

    const secondFactorModal=(title,submitLabel,onSubmit)=>{openActionModal(`<span class="eyebrow">SECURITY CHECK</span><h2 id="actionModalTitle">${esc(title)}</h2><p>Confirm your password and enter an authenticator or unused recovery code.</p><form id="secondFactorForm" class="market-form"><label>Current password<input name="password" type="password" required></label><label>Authenticator / recovery code<input name="code" autocomplete="one-time-code" required></label><button class="primary-btn wide">${esc(submitLabel)}</button></form>`);$('#secondFactorForm').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget);await onSubmit({password:f.get('password'),code:f.get('code')});};};
    $('#disable2fa')?.addEventListener('click',()=>secondFactorModal('Disable two-factor authentication?','Disable 2FA',async body=>{try{await api('/security/2fa/disable',{method:'POST',body:JSON.stringify(body)});closeActionModal();toast('2FA disabled');renderAccount(new URLSearchParams('tab=security'));}catch(error){toast(error.message,'error');}}));
    $('#regenerateRecovery')?.addEventListener('click',()=>secondFactorModal('Generate new recovery codes','Generate codes',async body=>{try{const result=await api('/security/2fa/recovery-codes/regenerate',{method:'POST',body:JSON.stringify(body)});$('#actionModalContent').innerHTML=`<span class="eyebrow">NEW RECOVERY CODES</span><h2 id="actionModalTitle">Replace your old codes.</h2><p>All previous recovery codes are now invalid.</p><div class="recovery-code-grid">${result.recoveryCodes.map(code=>`<code>${esc(code)}</code>`).join('')}</div><button class="primary-btn wide" id="finishRecovery">I've saved them</button>`;$('#finishRecovery').onclick=()=>{closeActionModal();renderAccount(new URLSearchParams('tab=security'));};}catch(error){toast(error.message,'error');}}));
    $$('[data-revoke]').forEach(b=>b.onclick=async()=>{try{await api(`/security/sessions/${b.closest('[data-session]').dataset.session}`,{method:'DELETE'});toast('Session signed out');renderAccount(new URLSearchParams('tab=security'));}catch(error){toast(error.message,'error');}});
    $('#revokeOthers').onclick=async()=>{try{await api('/security/sessions/revoke-others',{method:'POST'});toast('Other devices signed out');renderAccount(new URLSearchParams('tab=security'));}catch(error){toast(error.message,'error');}};
    $('#logoutButton').onclick=logout;
  }

  function renderAccountRequired(title,copy){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">SANDMAN / ACCOUNT</span><h1>${esc(title)}.</h1><p>${esc(copy)}</p><button class="primary-btn" id="accountRequiredLogin">Log in</button></div></section></div>`;$('#accountRequiredLogin').onclick=()=>openAuth('login');}

  async function renderNotifications(){if(!state.token)return renderAccountRequired('Notifications','Log in to see updates.');await loadNotifications();app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">NOTIFICATIONS</span><h1>Your updates.</h1></div><button class="secondary-btn" id="readAll">Mark all read</button></div><div class="notification-list">${state.notifications.items.length?state.notifications.items.map(n=>`<a class="notification-item ${n.readAt?'':'unread'}" href="${esc(n.link||'#/account')}" data-notice="${n.id}"><div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${new Date(n.createdAt).toLocaleString()}</small></div><span>${n.readAt?'':'●'}</span></a>`).join(''):emptyProducts('No notifications yet.')}</div></div>`;$$('[data-notice]').forEach(a=>a.onclick=()=>api(`/experience/notifications/${a.dataset.notice}/read`,{method:'PATCH'}).catch(()=>{}));$('#readAll').onclick=async()=>{await api('/experience/notifications/read-all',{method:'POST'});await loadNotifications();renderNotifications();};}

  async function renderCheckout(){if(!state.token)return renderAccountRequired('Checkout','Log in before checking out.');await loadCart(false);if(!state.cart?.items?.length){app.innerHTML='<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Your bag is empty.</h1><a class="primary-btn" href="#/shop">Shop parts</a></div></section></div>';return;}const preflight=await api('/v2/checkout/preflight').catch(()=>null);if(preflight&&!preflight.ready){app.innerHTML=`<div class="checkout-page"><div class="v2-tool-card"><span class="eyebrow">CHECKOUT / PREFLIGHT</span><h2>Fix these before payment.</h2>${preflight.issues.map(i=>`<div class="request-row"><strong>${esc(i.message)}</strong><span>${esc(titleCase(i.code))}</span></div>`).join('')}<div class="variant-actions"><a class="secondary-btn" href="#/garage">Check garage</a><a class="primary-btn" href="#/shop">Back to shop</a></div></div></div>`;return;}state.paymentConfig=state.paymentConfig||await api('/payments/config');const hasMarketplace=state.cart.items.some(i=>i.product.sourceType==='MARKETPLACE');const methods=[];if(state.paymentConfig.stripe.enabled)methods.push('<label class="payment-choice"><input type="radio" name="paymentProvider" value="stripe" checked><span><strong>Card + wallets</strong><small>Stripe shows eligible cards, wallets, bank and local methods.</small></span></label>');if(state.paymentConfig.paypal.enabled&&!hasMarketplace)methods.push(`<label class="payment-choice"><input type="radio" name="paymentProvider" value="paypal" ${methods.length?'':'checked'}><span><strong>PayPal</strong><small>Pay with PayPal.</small></span></label>`);if(state.paymentConfig.bankTransfer.enabled&&!hasMarketplace)methods.push(`<label class="payment-choice"><input type="radio" name="paymentProvider" value="bank_transfer" ${methods.length?'':'checked'}><span><strong>Bank transfer / EFT</strong><small>Order remains pending until verified.</small></span></label>`);app.innerHTML=`<div class="checkout-page"><div class="checkout-layout"><form class="checkout-form" id="checkoutForm"><span class="eyebrow">CHECKOUT / DELIVERY</span><h2>Shipping address</h2><div class="field-row"><label>First name<input name="firstName" required value="${esc(state.user?.firstName||'')}"></label><label>Last name<input name="lastName" required value="${esc(state.user?.lastName||'')}"></label></div><label>Address<input name="line1" required></label><label>Address line 2<input name="line2"></label><div class="field-row"><label>City<input name="city" required></label><label>State / province<input name="state"></label></div><div class="field-row"><label>Postal code<input name="postalCode" required></label><label>Country code<select name="country"><option value="ZA">South Africa</option><option value="US">United States</option><option value="GB">United Kingdom</option><option value="DE">Germany</option><option value="AU">Australia</option><option value="CA">Canada</option></select></label></div><label>Phone<input name="phone"></label><label>Promo code<div class="inline-field"><input name="promoCode" id="promoCode"><button type="button" class="secondary-btn" id="applyPromo">Apply</button></div></label><label>Order note<textarea name="customerNote" rows="3"></textarea></label><div class="payment-methods"><span class="eyebrow">PAYMENT</span>${methods.join('')||'<p>No payment provider configured.</p>'}${hasMarketplace?'<p class="form-note">Marketplace carts use Stripe so seller payouts can be handled securely.</p>':''}</div><button class="primary-btn wide" type="submit" ${methods.length?'':'disabled'}>Continue to secure payment</button></form><aside class="order-summary"><span class="eyebrow">ORDER / SUMMARY</span>${state.cart.items.map(i=>`<div class="summary-item">${imageOf(i.product)?`<img src="${esc(imageOf(i.product))}" alt="">`:''}<div><strong>${esc(i.product.name)}</strong><span>Qty ${i.quantity}${i.offer?' · offer price':''}</span></div><strong>${money((i.effectiveUnitPriceCents??i.product.priceCents)*i.quantity)}</strong></div>`).join('')}<div class="summary-totals" id="quoteTotals"></div></aside></div></div>`;const addressFrom=()=>{const f=new FormData($('#checkoutForm'));return{firstName:f.get('firstName'),lastName:f.get('lastName'),line1:f.get('line1')||'Quote only',line2:f.get('line2')||undefined,city:f.get('city')||'Quote',state:f.get('state')||undefined,postalCode:f.get('postalCode')||'0000',country:f.get('country')||'ZA',phone:f.get('phone')||undefined};};const quote=async()=>{try{const f=new FormData($('#checkoutForm'));const q=await api('/orders/quote',{method:'POST',body:JSON.stringify({shippingAddress:addressFrom(),promoCode:f.get('promoCode')||undefined})});$('#quoteTotals').innerHTML=`<div class="summary-line"><span>Subtotal</span><span>${money(q.subtotalCents)}</span></div>${q.discountCents?`<div class="summary-line"><span>Discount ${q.promoCode?`(${esc(q.promoCode)})`:''}</span><span>−${money(q.discountCents)}</span></div>`:''}<div class="summary-line"><span>Shipping</span><span>${money(q.shippingCents)}</span></div><div class="summary-line"><span>Tax</span><span>${money(q.taxCents)}</span></div><div class="summary-line total"><span>Total</span><span>${money(q.totalCents)}</span></div>`;}catch(e){toast(e.message,'error');}};$('#applyPromo').onclick=quote;await quote();$('#checkoutForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),btn=e.currentTarget.querySelector('button[type=submit]');btn.disabled=true;btn.textContent='Creating secure payment…';try{const result=await api('/orders/checkout',{method:'POST',body:JSON.stringify({shippingAddress:addressFrom(),customerNote:f.get('customerNote')||undefined,paymentProvider:f.get('paymentProvider'),promoCode:f.get('promoCode')||undefined})});if(result.payment.provider==='stripe')await renderStripePayment(result);else if(result.payment.provider==='paypal')await renderPayPalPayment(result);else e.currentTarget.innerHTML=`<span class="eyebrow">BANK TRANSFER / EFT</span><h2>Order ${esc(result.order.orderNumber)}</h2><div class="bank-instructions">${esc(result.payment.instructions).replaceAll('\n','<br>')}</div><a class="primary-btn wide" href="#/order/${encodeURIComponent(result.order.orderNumber)}">View order</a>`;}catch(err){toast(err.message,'error');btn.disabled=false;btn.textContent='Continue to secure payment';}};}

  function loadExternalScript(src,globalName){if(globalName&&window[globalName])return Promise.resolve(window[globalName]);return new Promise((resolve,reject)=>{const existing=[...document.scripts].find(s=>s.src===src);if(existing){existing.addEventListener('load',()=>resolve(globalName?window[globalName]:true),{once:true});return;}const script=document.createElement('script');script.src=src;script.async=true;script.onload=()=>resolve(globalName?window[globalName]:true);script.onerror=()=>reject(new Error('Could not load secure payment provider'));document.head.appendChild(script);});}
  async function renderStripePayment(result){await loadExternalScript('https://js.stripe.com/v3/','Stripe');const stripe=window.Stripe(result.payment.publishableKey||state.paymentConfig.stripe.publishableKey);const elements=stripe.elements({clientSecret:result.payment.clientSecret,appearance:currentTheme()==='light'?{theme:'stripe',variables:{colorPrimary:'#151310',colorBackground:'#fffdf8',colorText:'#151310',borderRadius:'0px'}}:{theme:'night',variables:{colorPrimary:'#dfc78d',colorBackground:'#0b0b0a',colorText:'#eee6da',borderRadius:'0px'}}});const form=$('#checkoutForm');form.innerHTML=`<span class="eyebrow">SECURE PAYMENT / STRIPE</span><h2>Pay ${money(result.order.totalCents)}</h2><div id="stripePaymentElement" class="provider-element"></div><button class="primary-btn wide" id="stripePayButton" type="button">Pay now</button><p class="form-note" id="paymentMessage"></p>`;elements.create('payment',{layout:'accordion'}).mount('#stripePaymentElement');$('#stripePayButton').onclick=async()=>{const b=$('#stripePayButton');b.disabled=true;b.textContent='Processing…';const {error}=await stripe.confirmPayment({elements,confirmParams:{return_url:`${location.origin}/orders/${encodeURIComponent(result.order.orderNumber)}`},redirect:'if_required'});if(error){$('#paymentMessage').textContent=error.message||'Payment failed';b.disabled=false;b.textContent='Pay now';return;}toast('Payment submitted');navigate(`/orders/${encodeURIComponent(result.order.orderNumber)}`);};}
  async function renderPayPalPayment(result){const config=state.paymentConfig.paypal,src=`https://www.paypal.com/sdk/js?client-id=${encodeURIComponent(config.clientId)}&currency=${encodeURIComponent(result.order.currency)}&intent=capture`;await loadExternalScript(src,'paypal');const form=$('#checkoutForm');form.innerHTML=`<span class="eyebrow">SECURE PAYMENT / PAYPAL</span><h2>Pay ${money(result.order.totalCents)}</h2><div id="paypalButtons" class="provider-element"></div><p class="form-note" id="paymentMessage"></p>`;await window.paypal.Buttons({createOrder:()=>result.payment.paypalOrderId,onApprove:async()=>{const captured=await api(`/orders/${encodeURIComponent(result.order.orderNumber)}/paypal/capture`,{method:'POST'});toast('PayPal payment complete');navigate(`/orders/${encodeURIComponent(captured.order.orderNumber)}`);},onError:err=>{$('#paymentMessage').textContent=err?.message||'PayPal payment failed';}}).render('#paypalButtons');}

  async function renderReturnsCenter(){
    if(!state.token)return renderAccountRequired('Returns Center','Log in to start or track a return.');
    const [cases,orders]=await Promise.all([api('/support/cases').catch(()=>[]),api('/orders').catch(()=>[])]);
    const eligible=orders.filter(order=>['PAID','PARTIALLY_REFUNDED'].includes(order.paymentStatus));
    setPageMeta('Returns Center — SANDMAN','Start a return, upload evidence and track buyer-protection cases.','/returns-center');
    app.innerHTML=`<div class="returns-center"><div class="dashboard-head"><div><span class="eyebrow">RETURNS / BUYER PROTECTION</span><h1>Returns Center.</h1><p>Start from the original order, add clear evidence, and keep everything in one case timeline.</p></div></div><div class="returns-grid"><section class="returns-list"><span class="eyebrow">YOUR CASES</span><h2>Case history.</h2>${cases.length?cases.map(item=>`<article class="return-case-card"><strong>${titleCase(item.type)} · ${esc(item.order.orderNumber)}</strong><small>${esc(item.reason)} · ${titleCase(item.status)} · ${fmtDate(item.createdAt)}</small>${item.refund?.amountCents?`<small>Refund ${money(item.refund.amountCents,item.order.currency)}</small>`:''}</article>`).join(''):emptyProducts('No return or buyer-protection cases yet.')}</section><section class="returns-form-card"><span class="eyebrow">START A CASE</span><h2>Tell us what happened.</h2>${eligible.length?`<form id="returnCaseForm" class="market-form"><label>Order<select name="orderNumber" id="returnOrder" required><option value="">Choose an order</option>${eligible.map(order=>`<option value="${esc(order.orderNumber)}">${esc(order.orderNumber)} · ${money(order.totalCents,order.currency)}</option>`).join('')}</select></label><label>Item<select name="orderItemId" id="returnItem"><option value="">Whole order / not item-specific</option></select></label><label>Issue<select name="type" required>${['RETURN','NOT_RECEIVED','WRONG_ITEM','DAMAGED','NOT_AS_DESCRIBED','COUNTERFEIT','OTHER'].map(type=>`<option value="${type}">${titleCase(type)}</option>`).join('')}</select></label><label>Short reason<input name="reason" minlength="5" maxlength="300" required placeholder="Part arrived damaged"></label><label>Details<textarea name="details" rows="5" maxlength="4000" placeholder="Describe what happened and what resolution you are requesting."></textarea></label><label class="upload-drop">Evidence photos<input name="evidence" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><span class="upload-drop-icon">＋</span><strong>Add photos</strong><small>Up to 8 JPG, PNG or WebP images</small></label><div class="review-upload-grid" id="returnEvidencePreview"></div><button class="primary-btn wide" type="submit">Open case</button></form>`:'<p>You do not have an eligible paid order yet.</p>'}</section></div></div>`;
    if(!eligible.length)return;
    const orderSelect=$('#returnOrder'),itemSelect=$('#returnItem'),form=$('#returnCaseForm'),evidence=form.elements.evidence;
    const syncItems=()=>{const order=eligible.find(item=>item.orderNumber===orderSelect.value);itemSelect.innerHTML='<option value="">Whole order / not item-specific</option>'+(order?.items||[]).map(item=>`<option value="${esc(item.id)}">${esc(item.name)} · ${esc(item.sku)}</option>`).join('');};
    orderSelect.onchange=syncItems;
    evidence.onchange=()=>{$('#returnEvidencePreview').innerHTML=[...evidence.files].slice(0,8).map(file=>`<span>${esc(file.name)}</span>`).join('');};
    form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Uploading evidence…';try{const data=new FormData(form);const uploads=[...evidence.files].length?await uploadProductImages([...evidence.files].slice(0,8),'returns'):[];await api('/support/cases',{method:'POST',body:JSON.stringify({orderNumber:data.get('orderNumber'),orderItemId:data.get('orderItemId')||undefined,type:data.get('type'),reason:data.get('reason'),details:data.get('details')||undefined,evidenceUrls:uploads.map(item=>item.url)})});toast('Case opened');renderReturnsCenter();}catch(error){toast(error.message,'error');button.disabled=false;button.textContent='Open case';}};
  }

  async function renderOrder(orderNumber){
    if(!state.token)return renderAccountRequired('Order','Log in to view this order.');
    app.innerHTML='<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Loading order…</h1></div></section></div>';
    try{
      const o=await api(`/orders/${encodeURIComponent(orderNumber)}`);
      setPageMeta(`Order ${o.orderNumber} — SANDMAN`,'Track your SANDMAN order, shipment activity and support options.',`/orders/${encodeURIComponent(o.orderNumber)}`);
      const events=[...(o.events||[])].sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));
      const fulfillments=o.fulfillments||[];
      app.innerHTML=`<div class="dashboard-page"><div class="dashboard-head"><div><span class="eyebrow">ORDER / ${esc(o.orderNumber)}</span><h1>${titleCase(o.status)}.</h1><p>${money(o.totalCents)} · Payment ${titleCase(o.paymentStatus)} · ${fmtDate(o.createdAt)}</p></div><a class="secondary-btn" href="/account?tab=purchases">All orders</a></div><div class="order-timeline"><div class="timeline-step done"><span>1</span><div><strong>Order placed</strong><small>${fmtDate(o.createdAt)}</small></div></div><div class="timeline-step ${['PAID','PROCESSING','SUBMITTED_TO_SUPPLIER','PARTIALLY_FULFILLED','FULFILLED'].includes(o.status)?'done':''}"><span>2</span><div><strong>Payment confirmed</strong><small>${titleCase(o.paymentStatus)}</small></div></div><div class="timeline-step ${['PROCESSING','SUBMITTED_TO_SUPPLIER','PARTIALLY_FULFILLED','FULFILLED'].includes(o.status)?'done':''}"><span>3</span><div><strong>Processing / shipped</strong><small>Supplier and seller tracking below</small></div></div><div class="timeline-step ${o.status==='FULFILLED'?'done':''}"><span>4</span><div><strong>Shipped / fulfilled</strong><small>${o.status==='FULFILLED'?'All fulfillment lines have shipped':'Waiting for final shipment update'}</small></div></div></div><div class="data-list">${o.items.map(i=>`<div class="data-row order-item-row" data-order-item="${i.id}"><div><strong>${esc(i.name)}</strong><small>${esc(i.sku)} · Qty ${i.quantity} · ${i.sourceType==='MARKETPLACE'?'Marketplace':'Supplier stock'}</small></div><span>${money(i.totalPriceCents)}</span><div>${i.sellerTrackingNumber?`<span class="status">${esc(i.sellerCarrier||'Carrier')} · ${esc(i.sellerTrackingNumber)}</span>${i.sellerTrackingUrl?`<a class="tracking-link" href="${esc(i.sellerTrackingUrl)}" target="_blank" rel="noreferrer">Track package ↗</a>`:''}`:'<span class="status">Tracking pending</span>'}</div>${['PAID','PARTIALLY_REFUNDED'].includes(o.paymentStatus)&&i.productId?`<button class="text-link" data-review-product="${i.productId}" data-product-name="${esc(i.name)}" data-seller="${i.sellerId||''}">Review</button>`:''}</div>`).join('')}</div>${fulfillments.length?`<section class="order-events"><h2>Fulfillment</h2>${fulfillments.map(f=>`<div class="event-line"><strong>Supplier fulfillment</strong><span>${titleCase(f.status)}${f.trackingNumber?` · ${esc(f.carrier||'')} ${esc(f.trackingNumber)}${f.trackingUrl?` · <a class="tracking-link" href="${esc(f.trackingUrl)}" target="_blank" rel="noreferrer">Track ↗</a>`:''}`:''}</span></div>`).join('')}</section>`:''}<section class="order-events"><h2>Order activity</h2>${events.length?events.map(e=>`<div class="event-line"><strong>${esc(e.message)}</strong><span>${new Date(e.createdAt).toLocaleString()}</span></div>`).join(''):'<p>No activity yet.</p>'}</section><div class="order-actions"><a class="secondary-btn" href="/returns-center">Start return / buyer protection</a></div></div>`;
      $$('[data-review-product]').forEach(btn=>btn.onclick=()=>openReviewComposer({productId:btn.dataset.reviewProduct,orderItemId:btn.closest('[data-order-item]').dataset.orderItem,sellerId:btn.dataset.seller||null,productName:btn.dataset.productName||'your part'}));
    }catch(e){app.innerHTML=emptyProducts(e.message);}
  }


  function renderPolicy(type){
    const policies={
      'buyer-protection':{eyebrow:'TRUST / BUYER PROTECTION',title:'Buyer protection',intro:'A clear path when an eligible order is not received, arrives damaged, is materially different from the listing, or raises authenticity concerns.',sections:[['When to open a case','Open a support case from your SANDMAN account when there is a genuine order problem. Keep the item, packaging, tracking information and useful photos until the case is resolved.'],['How review works','SANDMAN can use the order record, payment status, seller or supplier information, shipment tracking, messages and evidence supplied by both sides to review a case.'],['Possible outcomes','Depending on the order, payment method, listing terms and applicable law, a case may result in replacement instructions, a return, a partial adjustment, a refund, or no adjustment when the claim is not supported.']]},
      shipping:{eyebrow:'HELP / SHIPPING',title:'Shipping',intro:'Supplier-stocked products and marketplace listings can have different delivery routes, lead times and carriers.',sections:[['Estimates','Available shipping estimates are shown on product pages when SANDMAN has them. The final shipping charge and destination details are confirmed during checkout.'],['Tracking','Tracking is attached to the order when the connected supplier or marketplace seller provides it. Customers can follow order progress from their account.'],['International orders','Cross-border orders can be affected by carrier delays, customs processing, duties, taxes or import restrictions. These can vary by destination and are not always controlled by SANDMAN.']]},
      returns:{eyebrow:'HELP / RETURNS',title:'Returns & refunds',intro:'Return eligibility depends on the specific product, its condition, seller or supplier terms, warranty information and applicable consumer law.',sections:[['Start with the order','Open the relevant order or support case before sending anything back. Do not ship a return until return instructions and the correct destination have been confirmed.'],['Condition matters','Parts should be kept complete and protected while a return is reviewed. Installed, modified, damaged or incorrectly handled parts may have different return eligibility depending on the reason for return.'],['Refund timing','Approved refunds are submitted through the original supported payment flow. The time it takes to appear can then depend on the payment provider and financial institution.']]},
      terms:{eyebrow:'LEGAL / PLATFORM TERMS',title:'Terms',intro:'SANDMAN combines connected supplier inventory with listings from independent marketplace sellers. These platform terms describe the basic rules of using that system.',sections:[['Accounts & lawful use','Users must provide accurate account and order information, use the platform lawfully, and must not attempt fraud, payment abuse, account takeover, scraping that harms the service, or other misuse.'],['Marketplace responsibilities','Independent sellers are responsible for lawful goods, accurate descriptions, condition, stock, fitment claims, shipping and tracking. Counterfeit, stolen or prohibited goods are not allowed.'],['Vehicle fitment','Where fitment matters, buyers should select the exact vehicle variant and review the evidence shown by SANDMAN. An UNKNOWN fitment state is not a promise that a part fits or does not fit.']]},
      privacy:{eyebrow:'LEGAL / PRIVACY',title:'Privacy',intro:'SANDMAN uses account, vehicle, order and marketplace information to operate the automotive commerce platform.',sections:[['Information used','This can include account details, saved Garage vehicles, builds, orders, addresses needed for fulfillment, support cases, marketplace activity and service-security records.'],['Payments','Raw card details are handled by payment providers rather than stored directly by SANDMAN. Payment records kept by SANDMAN are limited to the identifiers and status information needed to process and reconcile orders.'],['Security & control','SANDMAN uses short-lived access tokens and secure HttpOnly refresh sessions. Production privacy notices should also explain retention, lawful bases, regional rights and contact methods for the countries where the service operates.']]},
      about:{eyebrow:'ABOUT / SANDMAN',title:'Dream while awake.',intro:'SANDMAN is an automotive-parts platform built around the car itself — not just a generic product catalogue.',sections:[['Vehicle-first shopping','My Garage and Vehicle Finder let customers choose an exact vehicle and carry that context into search, fitment and shopping.'],['Build with evidence','SANDMAN distinguishes verified fitment, catalogue evidence, universal parts, explicit incompatibility and unknown fitment instead of inventing compatibility to make a sale.'],['One market','Connected supplier stock, independent marketplace listings, Builds, sourcing requests, reviews, checkout and operations live in one platform.']]}
    };
    const page=policies[type]||policies.about;
    const links=[['buyer-protection','Buyer protection'],['shipping','Shipping'],['returns','Returns'],['terms','Terms'],['privacy','Privacy'],['about','About']];
    app.innerHTML=`<div class="policy-page"><div class="policy-shell"><aside class="policy-nav"><a class="policy-wordmark" href="#/">SANDMAN</a><span class="eyebrow">INFORMATION</span>${links.map(([slug,label])=>`<a class="${slug===type?'active':''}" href="#/${slug}">${label}</a>`).join('')}</aside><article class="policy-content"><span class="eyebrow">${esc(page.eyebrow)}</span><h1>${esc(page.title)}</h1><p class="policy-intro">${esc(page.intro)}</p><div class="policy-sections">${page.sections.map(([heading,copy])=>`<section><h2>${esc(heading)}</h2><p>${esc(copy)}</p></section>`).join('')}</div>${type!=='about'?'<div class="policy-note"><strong>Production note</strong><p>This page is operational guidance for the current SANDMAN build. Final legal policies should be reviewed for every country where the business accepts orders.</p></div>':''}<div class="policy-actions"><a class="secondary-btn" href="#/shop">Continue shopping</a><a class="ghost-btn" href="#/account">Account & support</a></div></article></div></div>`;
  }

  async function renderResetPassword(params){const token=params.get('token');app.innerHTML=`<div class="form-page"><div class="form-layout"><div class="form-intro"><span class="eyebrow">ACCOUNT RECOVERY</span><h1>Set a new password.</h1></div><form id="resetPasswordForm" class="market-form"><label>New password<input name="password" type="password" minlength="10" required></label><label>Confirm password<input name="confirm" type="password" minlength="10" required></label><button class="primary-btn">Reset password</button></form></div></div>`;$('#resetPasswordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(f.get('password')!==f.get('confirm'))return toast('Passwords do not match','error');try{await api('/auth/reset-password',{method:'POST',body:JSON.stringify({token,newPassword:f.get('password')})});toast('Password reset. Log in again.');location.hash='#/';openAuth('login');}catch(err){toast(err.message,'error');}};}
  async function renderVerifyEmail(params){const token=params.get('token');try{await api('/auth/email-verification/confirm',{method:'POST',body:JSON.stringify({token})});if(state.token)state.user=await api('/auth/me');app.innerHTML='<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">EMAIL VERIFIED</span><h1>You’re verified.</h1><a class="primary-btn" href="#/account">Continue</a></div></section></div>';}catch(e){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Verification failed.</h1><p>${esc(e.message)}</p></div></section></div>`;}}
  async function renderEmailChange(params){const token=params.get('token');if(!state.token){renderAccountRequired('Confirm your new email','Log in to SANDMAN first, then this secure email-change link can be confirmed.');return;}if(!token){app.innerHTML='<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Email change link missing.</h1><a class="secondary-btn" href="/account?tab=profile">Account settings</a></div></section></div>';return;}try{const result=await api('/auth/email-change/confirm',{method:'POST',body:JSON.stringify({token})});setToken(result.token,result.user);await hydrateUser();app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">EMAIL UPDATED</span><h1>New email confirmed.</h1><p>Your SANDMAN sign-in email is now ${esc(state.user.email)}.</p><a class="primary-btn" href="/account?tab=profile">Account settings</a></div></section></div>`;}catch(e){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Email change failed.</h1><p>${esc(e.message)}</p><a class="secondary-btn" href="/account?tab=profile">Account settings</a></div></section></div>`;}}

  async function logout(){try{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:state.token?{Authorization:`Bearer ${state.token}`}:{}});}catch{}setToken('',null);state.cart=null;state.garage=[];state.builds=[];state.notifications={items:[],unread:0};updateCartCount();navigate('/');toast('Signed out');}

  async function route(){closeCart();closeAuth();closeActionModal();closeMobileMenu();closeSearch();document.body.classList.remove('filters-open');$$('.nav-dropdown[open]').forEach(d=>d.removeAttribute('open'));const {path,params}=queryFromHash();document.body.classList.toggle('product-page-active',path.startsWith('product/'));window.scrollTo(0,0);try{if(!path){setPageMeta('SANDMAN — Automotive Parts Marketplace','Vehicle-first automotive parts, verified fitment, supplier stock, marketplace sellers and builds.','/');await renderHome();}else if(path==='shop')await renderShop(params);else if(path.startsWith('product/'))await renderProduct(decodeURIComponent(path.slice(8)));else if(path==='vehicle-finder')await renderVehicleFinder();else if(path==='advisor')await renderAdvisor();else if(path==='requests')await renderRequests();else if(path==='garage')await renderGarage();else if(path==='builds')await renderBuilds();else if(path.startsWith('build/'))await renderBuild(path.slice(6));else if(path.startsWith('public-build/'))await renderPublicBuild(path.slice(13));else if(path==='compare')await renderCompare(params);else if(path==='wishlist')await renderWishlist();else if(path==='messages')await renderMessages(params);else if(path==='feed')await renderFeed();else if(path.startsWith('profile/'))await renderPublicProfile(decodeURIComponent(path.slice(8)));else if(path.startsWith('seller-profile/'))await renderSellerProfile(path.slice(15));else if(path==='sell')await renderSell(params);else if(path==='seller')await renderSeller(params);else if(path==='account')await renderAccount(params);else if(path==='notifications')await renderNotifications();else if(path==='checkout')await renderCheckout();else if(path.startsWith('order/'))await renderOrder(decodeURIComponent(path.slice(6)));else if(path==='returns-center')await renderReturnsCenter();else if(path==='reset-password')await renderResetPassword(params);else if(path==='verify-email')await renderVerifyEmail(params);else if(path==='email-change')await renderEmailChange(params);else if(['buyer-protection','shipping','returns','terms','privacy','about'].includes(path)){setPageMeta(`${titleCase(path)} — SANDMAN`,`${titleCase(path)} information for SANDMAN customers.`,`/${path}`);renderPolicy(path);}else app.innerHTML='<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><span class="eyebrow">404 / SANDMAN</span><h1>Lost in the market.</h1><a class="primary-btn" href="/">Return home</a></div></section></div>';}catch(e){app.innerHTML=`<div class="page-shell"><section class="page-hero"><div class="page-hero-inner"><h1>Something went wrong.</h1><p>${esc(e.message)}</p><a class="secondary-btn" href="/">Home</a></div></section></div>`;}app.focus({preventScroll:true});}

  function bindGlobalUi(){
    window.addEventListener('scroll',()=>$('#siteHeader').classList.toggle('scrolled',scrollY>20),{passive:true});
    window.addEventListener('popstate',route);
    window.addEventListener('hashchange',()=>{adoptLegacyHash();route();});
    $('#searchToggle').onclick=()=>{const p=$('#searchPanel');p.classList.toggle('open');p.setAttribute('aria-hidden',p.classList.contains('open')?'false':'true');if(p.classList.contains('open'))setTimeout(()=>$('#globalSearchInput').focus(),100);};
    $('#globalSearchForm').onsubmit=e=>{e.preventDefault();const q=$('#globalSearchInput').value.trim();closeSearch();navigate(`/shop${q?`?q=${encodeURIComponent(q)}`:''}`);};
    $('#globalSearchInput').addEventListener('input',e=>{clearTimeout(state.searchTimer);state.searchController?.abort();const q=e.target.value.trim();if(!q){$('#searchSuggestions').innerHTML='';return;}state.searchTimer=setTimeout(async()=>{const controller=new AbortController();state.searchController=controller;try{const res=await fetch(`/api/experience/search/suggestions?q=${encodeURIComponent(q)}`,{credentials:'same-origin',signal:controller.signal,headers:state.token?{Authorization:`Bearer ${state.token}`}:{}});if(!res.ok)return;const d=await res.json();if(controller.signal.aborted)return;$('#searchSuggestions').innerHTML=`${d.exactPartNumber?`<div class="search-suggestion-group">Exact part number</div><a href="/products/${encodeURIComponent(d.exactPartNumber.slug)}"><strong>${esc(d.exactPartNumber.name)}</strong><small>${esc(d.exactPartNumber.manufacturerPn||d.exactPartNumber.sku)} · ${money(d.exactPartNumber.priceCents)}</small></a>`:''}${d.products?.length?'<div class="search-suggestion-group">Parts</div>':''}${(d.products||[]).filter(p=>p.id!==d.exactPartNumber?.id).map(p=>`<a href="/products/${encodeURIComponent(p.slug)}"><strong>${esc(p.name)}</strong><small>${esc(p.brand||p.sku)} · ${money(p.priceCents)}</small></a>`).join('')}${d.engines?.length?'<div class="search-suggestion-group">Vehicles & engines</div>':''}${(d.engines||[]).map(v=>`<a href="/shop?q=${encodeURIComponent(v.engineCode)}"><strong>${esc(v.engineCode)}</strong><small>${esc(`${v.model.make.name} ${v.model.name} · ${v.engineName}`)}</small></a>`).join('')}${d.categories?.length?'<div class="search-suggestion-group">Categories</div>':''}${(d.categories||[]).map(c=>`<a href="/shop?category=${encodeURIComponent(c.slug)}"><strong>${esc(c.name)}</strong><small>Category</small></a>`).join('')}${d.brands?.length?'<div class="search-suggestion-group">Brands</div>':''}${(d.brands||[]).map(b=>`<a href="/shop?q=${encodeURIComponent(b)}"><strong>${esc(b)}</strong><small>Brand</small></a>`).join('')}`;}catch(err){if(err.name!=='AbortError')$('#searchSuggestions').innerHTML='';}},220);});
    $$('.nav-dropdown').forEach(dropdown=>dropdown.addEventListener('toggle',()=>{if(dropdown.open)$$('.nav-dropdown').forEach(other=>{if(other!==dropdown)other.removeAttribute('open');});}));
    $('#accountButton').onclick=()=>state.token?navigate('/account'):openAuth('login');
    $('#mobileAccountButton').onclick=()=>state.token?navigate('/account'):openAuth('login');
    $('#notificationButton').onclick=()=>state.token?navigate('/notifications'):openAuth('login');
    $('#cartButton').onclick=openCart;
    $('#cartClose').onclick=closeCart;
    $('#authClose').onclick=closeAuth;
    $('#actionModalClose').onclick=closeActionModal;
    $('#backdrop').onclick=()=>{closeCart();closeAuth();closeActionModal();};
    $('#mobileMenuButton').onclick=()=>{$('#mobileMenu').classList.add('open');$('#mobileMenu').setAttribute('aria-hidden','false');document.body.classList.add('mobile-menu-open');};
    $('#mobileMenuClose').onclick=closeMobileMenu;
    $$('#mobileMenu a').forEach(a=>a.onclick=closeMobileMenu);
    $$('.auth-tabs button').forEach(b=>b.onclick=()=>switchAuthTab(b.dataset.authTab));
    $('#forgotPasswordButton').onclick=()=>{closeAuth();openActionModal(`<span class="eyebrow">ACCOUNT RECOVERY</span><h2 id="actionModalTitle">Reset your password.</h2><p>Enter your email and SANDMAN will send a time-limited reset link if the account exists.</p><form id="forgotPasswordForm" class="market-form"><label>Email address<input name="email" type="email" autocomplete="email" required autofocus></label><button class="primary-btn wide">Send reset email</button></form>`);$('#forgotPasswordForm').onsubmit=async event=>{event.preventDefault();const email=new FormData(event.currentTarget).get('email');try{await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email})});closeActionModal();toast('If that account exists, a reset email was sent.');}catch(error){toast(error.message,'error');}};};
    const finishLogin=async data=>{setToken(data.token,data.user);await hydrateUser();closeAuth();closeActionModal();toast(`Welcome back${data.user.firstName?`, ${data.user.firstName}`:''}`);route();};
    $('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const data=await api('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});if(data.requiresTwoFactor){closeAuth();openActionModal(`<span class="eyebrow">TWO-FACTOR AUTHENTICATION</span><h2 id="actionModalTitle">Confirm it’s you.</h2><p>Enter the six-digit code from your authenticator app, or use one unused recovery code.</p><form id="login2faForm" class="market-form"><label>Authenticator / recovery code<input name="code" autocomplete="one-time-code" inputmode="numeric" required autofocus></label><button class="primary-btn wide">Continue securely</button></form>`);$('#login2faForm').onsubmit=async event=>{event.preventDefault();try{const verified=await api('/auth/login/2fa',{method:'POST',body:JSON.stringify({challengeToken:data.challengeToken,code:new FormData(event.currentTarget).get('code')})});await finishLogin(verified);if(verified.usedRecoveryCode)toast('Signed in with a recovery code — consider generating a new set.');}catch(error){toast(error.message,'error');}};return;}await finishLogin(data);}catch(err){toast(err.message,'error');}};
    $('#registerForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const data=await api('/auth/register',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),firstName:f.get('firstName'),lastName:f.get('lastName')})});setToken(data.token,data.user);await hydrateUser();closeAuth();toast(data.verificationEmailSent ? 'Account created — check your email to verify it' : 'Account created — verification email could not be sent yet', data.verificationEmailSent ? 'success' : 'error');route();}catch(err){toast(err.message,'error');}};
    document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCart();closeAuth();closeActionModal();closeMobileMenu();closeSearch();}});
    document.addEventListener('click',e=>{
      if(!e.target.closest('.nav-dropdown'))$$('.nav-dropdown[open]').forEach(d=>d.removeAttribute('open'));
      if(e.target.closest('[data-compare-id]'))return;
      const anchor=e.target.closest('a[href]');
      if(!anchor||anchor.target==='_blank'||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
      const href=anchor.getAttribute('href')||'';
      if(href.startsWith('#/')){e.preventDefault();navigate(href);return;}
      if(href.startsWith('/')&&!href.startsWith('/api/')&&!href.startsWith('/admin')&&!href.startsWith('/assets/')&&!href.startsWith('/store/')){e.preventDefault();navigate(href);}
    });
  }


  async function boot(){
    syncThemeUi();
    $$('[data-theme-toggle]').forEach(button => button.addEventListener('click', toggleTheme));
    bindGlobalUi();
    adoptLegacyHash();
    await Promise.all([loadCategories(),hydrateUser()]);
    updateCartCount();
    await route();
    setInterval(() => { if (state.token && !document.hidden) loadNotifications().catch(() => {}); }, 30000);
  }
  boot();
})();
